,p_name=>'O que ele tem hoje'
,p_parent_plug_id=>wwv_flow_api.id(284309336428317150400)
,p_template=>wwv_flow_api.id(281503492925310346642)
,p_display_sequence=>170
,p_region_css_classes=>'nc-ben-hoje'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--scrollBody:t-Form--slimPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'BODY'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('select DISTINCT initcap(b.descricao_familia) Benef\00EDcio, initcap(t.descricao_tipo)||decode(v.desconta_saldo,''N'','' (N\00E3o Desconta Saldo)'') Tipo_Benef\00EDcio, CASE WHEN v.desconta_saldo = ''S'' THEN /*nvl((nvl(i.quantidade,1)*i.valor_beneficio),v.valor_tipo *')
||' nvl(v.quantidade,1))*/DECODE(nvl((nvl(i.quantidade,1)*i.valor_beneficio),0),0,(v.valor_tipo * nvl(v.quantidade,1)),(nvl(i.quantidade,1)*i.valor_beneficio)) WHEN v.desconta_saldo = ''N'' THEN null end Valor_Total',
'  from beneficios_familia b, beneficios_familia_tipo t, beneficios_fam_tipo_vlr v, incor_beneficios_funcionais i',
' where b.cod_empresa = t.cod_empresa',
'   and b.cod_empresa = v.cod_empresa',
'   and b.cod_empresa = i.cod_empresa',
'   and b.cod_familia = i.flag',
'   and b.cod_familia = t.cod_familia',
'   and b.cod_familia = v.cod_familia',
'   and t.tipo_cod_familia = v.tipo_cod_familia',
'   and t.tipo_cod_familia = i.tipo',
'   and nvl(v.desconta_saldo,''N'') = ''S''',
'   and nvl(:P116_DT_SOLICITACAO,sysdate) between b.dt_inicio_familia and nvl(b.dt_fim_familia,sysdate)',
'   and nvl(:P116_DT_SOLICITACAO,sysdate) between t.dt_inicio_tipo and nvl(t.dt_fim_tipo,sysdate)',
'   and nvl(:P116_DT_SOLICITACAO,sysdate) between v.dt_inicio_valor and nvl(v.dt_fim_valor,sysdate)',
'   and nvl(:P116_DT_SOLICITACAO,sysdate) between i.dt_inicio and nvl(i.dt_fim,sysdate)',
'   and i.cod_empresa = :p116_cod_empresa_solicitado',
'   and i.matricula = :p116_mat_solicitado',
'   and ((:P116_cod_solicitacao is null) or (:P116_cod_solicitacao is not null and not exists (select 1 from req_beneficios_itens i where i.cod_req_alt_func = :P116_cod_solicitacao)))',
' union ',
unistr('select DISTINCT initcap(b.descricao_familia) Benef\00EDcio, initcap(t.descricao_tipo)||decode(v.desconta_saldo,''N'','' (N\00E3o Desconta Saldo)'') Tipo_Benef\00EDcio,  CASE WHEN v.desconta_saldo = ''S'' THEN nvl((nvl(i.quantidade,1)*i.valor),v.valor_tipo * nvl(v.quan')
||'tidade,1))  WHEN v.desconta_saldo = ''N'' THEN null end Valor_Total',
'  from beneficios_familia b, beneficios_familia_tipo t, beneficios_fam_tipo_vlr v, req_beneficios_itens i',
' where b.cod_empresa = t.cod_empresa',
'   and b.cod_empresa = v.cod_empresa',
'   and b.cod_familia = i.cod_familia',
'   and b.cod_familia = t.cod_familia',
'   and b.cod_familia = v.cod_familia',
'   and t.tipo_cod_familia = v.tipo_cod_familia',
'   and t.tipo_cod_familia = i.tipo_cod_familia',
'   and b.cod_empresa = nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'   and :P116_dt_solicitacao between b.dt_inicio_familia and nvl(b.dt_fim_familia,sysdate)',
'   and :P116_dt_solicitacao between t.dt_inicio_tipo and nvl(t.dt_fim_tipo,sysdate)',
'   and :P116_dt_solicitacao between v.dt_inicio_valor and nvl(v.dt_fim_valor,sysdate)',
'   and i.cod_req_alt_func = :P116_cod_solicitacao',
'   and (i.operacao is null or i.operacao = ''D'')',
' order by 1,2,3'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P116_COD_EMPRESA_SOLICITADO,P116_MAT_SOLICITADO,P116_DT_SOLICITACAO'
,p_query_row_template=>wwv_flow_api.id(281503501736864346658)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>'-'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
);
end;
