,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('select DISTINCT initcap(b.descricao_familia) Benef\00EDcio, initcap(t.descricao_tipo)||decode(v.desconta_saldo,''N'','' (N\00E3o Desconta Saldo)'') Tipo_Benef\00EDcio, case when v.desconta_saldo = ''S'' then DECODE(i.operacao,''D'',0,''I'',(nvl(i.quantidade,1)*i.valor),(n')
||'vl(i.quantidade,1)*i.valor)) when v.desconta_saldo = ''N'' then null end Valor_Total,  DECODE(i.operacao,''D'',(nvl(i.quantidade,1)*i.valor),null) valor_anterior, DECODE(i.operacao,''D'',''Removido'',''I'',''Inserido'',''-'') Tipo',
'  from beneficios_familia b, beneficios_familia_tipo t, beneficios_fam_tipo_vlr v, req_beneficios_itens i',
' where b.cod_empresa = t.cod_empresa',
'   and b.cod_empresa = v.cod_empresa',
'   and b.cod_familia = i.cod_familia',
'   and b.cod_familia = t.cod_familia',
'   and b.cod_familia = v.cod_familia',
'   and t.tipo_cod_familia = v.tipo_cod_familia',
