,p_button_position=>'REGION_TEMPLATE_CREATE'
,p_warn_on_unsaved_changes=>null
,p_button_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  VEFETIVACAO_INICIADA VARCHAR2(1) := ''N'';',
'BEGIN',
'  IF :P116_COD_SOLICITACAO IS NOT NULL THEN',
'    IF :P116_COD_SIT_SOLICITACAO = 1 THEN',
'      RETURN(TRUE);',
'    ELSIF :P116_COD_SIT_SOLICITACAO = 5 THEN',
'      BEGIN',
'        SELECT DISTINCT ''S''',
'        INTO   VEFETIVACAO_INICIADA',
'        FROM   SOLICITACAO_ALTERACAO_FUNC SAF',
'        WHERE  (EXISTS (SELECT 1 FROM SOLIC_APROV_PARC_SALARIO P WHERE P.EFETIVACAO = ''S'' AND P.COD_SOLICITACAO = SAF.COD_SOLICITACAO)',
'        OR     EXISTS (SELECT 1 FROM SOLICITACAO_APROVADAS SA WHERE SA.EFETIVACAO = ''S'' AND SA.COD_SOLICITACAO = SAF.COD_SOLICITACAO))',
'        AND    SAF.COD_SIT_SOLICITACAO = 5',
'        AND    SAF.COD_SOLICITACAO = :P116_COD_SOLICITACAO;',
'      EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'          VEFETIVACAO_INICIADA := ''N'';',
'      END;',
'      IF NVL(VEFETIVACAO_INICIADA,''N'') = ''S'' THEN',
'        RETURN(FALSE);',
'      ELSE',
'        RETURN(TRUE);',
'      END IF;',
'    ELSE',
'      RETURN(FALSE);',
'    END IF;',
'  ELSE',
'    RETURN(FALSE);',
'  END IF;',
'END;'))
,p_button_condition_type=>'FUNCTION_BODY'
);
