wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(785728284958276404)
,p_name=>'P116_NOVO_SINDICATO'
,p_item_sequence=>1930
,p_item_plug_id=>wwv_flow_api.id(275489987525077867997)
,p_prompt=>'Sindicato'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT S.COD||'' - ''||Initcap(S.sigla) descricao, S.COD codigo',
'FROM SINDICATOS S',
'WHERE S.COD_EMPRESA = :P116_COD_EMPRESA_NVL',
'and ((trunc(sysdate) >= nvl(s.dt_vigencia_inicial,trunc(sysdate)) and :P116_COD_SOLICITACAO is null) or (:P116_COD_SOLICITACAO is not null))',
'and nvl(s.sit,''A'') not in (''E'',''I'')',
'and s.cod <> 999',
'and not exists ',
'(',
'SELECT 1',
'FROM vw_sindicato_eleg sx',
'where SX.COD_EMPRESA = :P116_COD_EMPRESA_NVL',
'and ((trunc(sysdate) >= nvl(sx.dt_vigencia_inicial,trunc(sysdate)) and :P116_COD_SOLICITACAO is null) or (:P116_COD_SOLICITACAO is not null))',
'and (sx.filial = NVL(:P116_FILIAL_PROP,:P116_FILIAL) or sx.filial is null)',
'and (sx.cod_ccusto = NVL(:P116_COD_CCUSTO_PROP,:P116_COD_CCUSTO) or sx.cod_ccusto is null)',
'and (sx.cod_unidade_adm = NVL(:P116_UNIDADE_ADM_PROP,:P116_UNIDADE_ADM) or sx.cod_unidade_adm is null)',
'and (sx.cod_atividade = nvl(:p116_cod_atividade_prop,:P116_COD_ATIVIDADE) or sx.cod_atividade is null)',
'and (sx.cod_local_trab = nvl(:P116_COD_LOCAL_PROP,:P116_COD_LOCALIZACAO) or sx.cod_local_trab is null)',
'and exists (',
'select 1 from SINDICATO_FILIAIS sfy where sfy.cod_sindicato = sx.cod_sindicato and sfy.cod_empresa = sx.cod_empresa and sfy.filial = NVL(:P116_FILIAL_PROP,:P116_FILIAL) UNION',
'select 1 from SINDICATO_CCUSTO scy where scy.cod_sindicato = sx.cod_sindicato and scy.cod_empresa = sx.cod_empresa and scy.cod_ccusto = NVL(:P116_COD_CCUSTO_PROP,:P116_COD_CCUSTO) UNION',
'select 1 from SINDICATO_UNID_ADM suy where suy.cod_sindicato = sx.cod_sindicato and suy.cod_empresa = sx.cod_empresa and suy.cod_unidade_adm = NVL(:P116_UNIDADE_ADM_PROP,:P116_UNIDADE_ADM) UNION',
'select 1 from SINDICATO_ATIVIDADE say where say.cod_sindicato = sx.cod_sindicato and say.cod_empresa = sx.cod_empresa and say.cod_atividade = nvl(:p116_cod_atividade_prop,:P116_COD_ATIVIDADE) UNION',
'select 1 from SINDICATO_LOCAL_TRAB sly where sly.cod_sindicato = sx.cod_sindicato and sly.cod_empresa = sx.cod_empresa and sly.cod_local_trab = nvl(:P116_COD_LOCAL_PROP,:P116_COD_LOCALIZACAO)',
')',
')',
'union',
'SELECT Sx.COD_sindicato||'' - ''||Initcap(Sx.sigla) descricao, sx.cod_sindicato codigo',
'FROM vw_sindicato_eleg sx',
'where SX.COD_EMPRESA = :P116_COD_EMPRESA_NVL',
'and ((trunc(sysdate) >= nvl(sx.dt_vigencia_inicial,trunc(sysdate)) and :P116_COD_SOLICITACAO is null) or (:P116_COD_SOLICITACAO is not null))',
'and (sx.filial = NVL(:P116_FILIAL_PROP,:P116_FILIAL) or sx.filial is null)',
'and (sx.cod_ccusto = NVL(:P116_COD_CCUSTO_PROP,:P116_COD_CCUSTO) or sx.cod_ccusto is null)',
'and (sx.cod_unidade_adm = NVL(:P116_UNIDADE_ADM_PROP,:P116_UNIDADE_ADM) or sx.cod_unidade_adm is null)',
'and (sx.cod_atividade = nvl(:p116_cod_atividade_prop,:P116_COD_ATIVIDADE) or sx.cod_atividade is null)',
'and (sx.cod_local_trab = nvl(:P116_COD_LOCAL_PROP,:P116_COD_LOCALIZACAO) or sx.cod_local_trab is null)',
'and exists (',
'select 1 from SINDICATO_FILIAIS sfy where sfy.cod_sindicato = sx.cod_sindicato and sfy.cod_empresa = sx.cod_empresa and sfy.filial = NVL(:P116_FILIAL_PROP,:P116_FILIAL) UNION',
'select 1 from SINDICATO_CCUSTO scy where scy.cod_sindicato = sx.cod_sindicato and scy.cod_empresa = sx.cod_empresa and scy.cod_ccusto = NVL(:P116_COD_CCUSTO_PROP,:P116_COD_CCUSTO) UNION',
'select 1 from SINDICATO_UNID_ADM suy where suy.cod_sindicato = sx.cod_sindicato and suy.cod_empresa = sx.cod_empresa and suy.cod_unidade_adm = NVL(:P116_UNIDADE_ADM_PROP,:P116_UNIDADE_ADM) UNION',
'select 1 from SINDICATO_ATIVIDADE say where say.cod_sindicato = sx.cod_sindicato and say.cod_empresa = sx.cod_empresa and say.cod_atividade = nvl(:p116_cod_atividade_prop,:P116_COD_ATIVIDADE) UNION',
'select 1 from SINDICATO_LOCAL_TRAB sly where sly.cod_sindicato = sx.cod_sindicato and sly.cod_empresa = sx.cod_empresa and sly.cod_local_trab = nvl(:P116_COD_LOCAL_PROP,:P116_COD_LOCALIZACAO)',
')',
'order by 2'))
