wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(785737797706276408)
,p_name=>'P116_BENEFICIO'
,p_item_sequence=>2700
,p_item_plug_id=>wwv_flow_api.id(284394211151356187670)
,p_prompt=>'Grupo'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct initcap(b.descricao_familia) descricao, b.cod_familia',
'  from beneficios_familia b, beneficios_familia_tipo t, beneficios_fam_tipo_vlr v, TMP_VALIDA_ELEG_BENEFICIO i, cargos c, centro_de_custo cc',
' where b.cod_empresa = t.cod_empresa',
'   and b.cod_empresa = v.cod_empresa',
'   and b.cod_empresa = i.empresa',
'   and b.cod_empresa = cc.cod_empresa',
'   and b.cod_familia = t.cod_familia',
'   and b.cod_familia = v.cod_familia',
'   and t.tipo_cod_familia = v.tipo_cod_familia',
'   and i.cargo = c.cod',
'   and i.ccusto = cc.cod',
'   and sysdate between b.dt_inicio_familia and nvl(b.dt_fim_familia,sysdate)',
'   and sysdate between t.dt_inicio_tipo and nvl(t.dt_fim_tipo,sysdate)',
'   and sysdate between v.dt_inicio_valor and nvl(v.dt_fim_valor,sysdate)',
'   and b.req_colab = ''S''',
'   and t.req_colab = ''S''',
'   and i.seq = :p116_seq_beneficio',
'   and fnct_valida_eleg_beneficio(i.empresa, ',
'                                  i.matricula, ',
'                                  i.vaga, ',
'                                  b.cod_familia, ',
'                                  t.tipo_cod_familia,',
'                                  trunc(sysdate),',
'                                  i.filial,',
'                                  c.class_cargo,',
'                                  i.grupo_sal,',
'                                  i.sindicato,',
'                                  i.ccusto,',
'                                  i.unid_adm,',
'                                  i.unid_neg, ',
'                                  i.atividade,',
'                                  null,',
'                                  i.perc_ben_var,',
'                                  i.cargo,',
'                                  i.rt_jornada_mensal,',
'                                  i.vinculo,',
'                                  i.seq,',
'                                  i.cod_horario) = ''S''',
'   and PKG_REQ_BENEFICIO.Benef_Prazo_Permitido(:p116_cod_empresa_solicitado, i.matricula,b.cod_familia, t.tipo_cod_familia,:p116_dt_vigencia_benef,''I'',:p116_cod_empresa_prop) = ''S''    ',
'   and ((b.cod_familia = ''BC'' and :p116_opcao = ''C'') or (:p116_opcao = ''O'' and b.cod_familia <> ''BC''))',
'   AND ((FNCT_BENEF_VALIDA_FORN_DIF (i.empresa,',
'                                   i.matricula,',
'                                   ''O'',',
'                                   T.FORNECEDOR) = ''S'' and :p116_opcao = ''C'') or ',
'        (FNCT_BENEF_VALIDA_FORN_DIF (i.empresa,',
'                                   i.matricula,',
'                                   ''BC'',',
'                                   b.cod_familia) = ''S'' and :p116_opcao = ''O''))',
'order by 2'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Selecione -'
,p_lov_cascade_parent_items=>'P116_OPCAO,P116_SEQ_BENEFICIO,P116_DT_VIGENCIA_BENEF,P116_COD_EMPRESA_PROP,P116_COD_EMPRESA_SOLICITADO'
,p_ajax_optimize_refresh=>'N'
,p_cHeight=>1
