'   and sysdate between b.dt_inicio_familia and nvl(b.dt_fim_familia,sysdate)',
'   and sysdate between t.dt_inicio_tipo and nvl(t.dt_fim_tipo,sysdate)',
'   and sysdate between v.dt_inicio_valor and nvl(v.dt_fim_valor,sysdate)',
'   and b.req_colab = ''S''',
'   and t.req_colab = ''S''',
'   and i.seq = :p116_seq_beneficio',
'   and fnct_valida_eleg_beneficio(i.empresa, ',
'                                  i.matricula, ',
'                                  i.vaga, ',
'                                  b.cod_familia, ',
'                                  t.tipo_cod_familia,',
'                                  trunc(sysdate),',
'                                  i.filial,',
'                                  c.class_cargo,',
'                                  i.grupo_sal,',
'                                  i.sindicato,',
'                                  i.ccusto,',
'                                  i.unid_adm,',
'                                  i.unid_neg, ',
'                                  i.atividade,',
'                                  null,',
'                                  i.perc_ben_var,',
'                                  i.cargo,',
'                                  i.rt_jornada_mensal,',
'                                  i.vinculo,',
'                                  i.seq,',
'                                  i.cod_horario) = ''S''',
'   and PKG_REQ_BENEFICIO.Benef_Prazo_Permitido(:p116_cod_empresa_solicitado, i.matricula,b.cod_familia, t.tipo_cod_familia,:p116_dt_vigencia_benef,''I'',:p116_cod_empresa_prop) = ''S''                               ',
'   AND B.COD_FAMILIA = :P116_BENEFICIO',
'   and (t.COD_EMPRESA, t.COD_FAMILIA, t.TIPO_COD_FAMILIA) not in ',
'   (select R.COD_EMPRESA, R.COD_FAMILIA, R.TIPO_COD_FAMILIA',
'      from REQ_BENEFICIOS_ITENS_TEMP R',
'     where R.cod_empresa = i.empresa',
'       and R.matricula = i.matricula',
'       and (R.operacao is null or r.operacao = ''I'')',
'     UNION ',
'    select TX.COD_EMPRESA, TX.COD_FAMILIA, TX.TIPO_COD_FAMILIA',
'      from REQ_BENEFICIOS_ITENS_TEMP TX, BENEFICIOS_FAMILIA B',
'     where TX.cod_empresa = i.empresa',
'       and TX.matricula = i.matricula',
'       AND TX.COD_EMPRESA = B.COD_EMPRESA',
'       AND TX.COD_FAMILIA = B.COD_FAMILIA',
'       AND B.CATEGORIA IN (''A'',''R'',''AR'')',
'       and (TX.operacao is null or TX.operacao = ''I''))',
'   AND (((FNCT_BENEF_VALIDA_FORN_DIF (i.empresa,',
'                                   i.matricula,',
'                                   ''O'',',
'                                   T.FORNECEDOR) = ''S'' AND :p116_opcao = ''C'') AND (FNCT_BENEF_VALIDA_FORN_DIF (i.empresa,',
'                                   i.matricula,',
'                                   ''C'',',
'                                   T.FORNECEDOR) = ''S'' AND :p116_opcao = ''C'')) OR ',
'        (FNCT_BENEF_VALIDA_FORN_DIF (i.empresa,',
'                                   i.matricula,',
'                                   ''C'',',
'                                   b.cod_familia) = ''S'' AND :p116_opcao = ''O'') OR',
'        (FNCT_BENEF_VALIDA_FORN_DIF (i.empresa,',
'                                   i.matricula,',
'                                   ''C'',',
'                                   T.FORNECEDOR) = ''S'' AND :p116_opcao = ''C''))',
' order by 1'))
