wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(785771906108276420)
,p_name=>'P116_CARGO_PROP'
,p_item_sequence=>2390
,p_item_plug_id=>wwv_flow_api.id(284430516097204389395)
,p_prompt=>'Cargo'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select x.descricao, x.cod',
'  from (',
'select SUBSTR(c.cod,1,7)||'' - ''||initcap(c.nome) descricao , cod',
'  from cargos_empresas e, cargos c, parametros_recursos_humanos p',
' where e.cod_empresa = p.cod_empresa',
'   and e.cod_cargo = c.cod',
'   and c.dt_term_vig_cargo > to_date(sysdate,''dd/mm/rrrr'')',
'   and e.cod_empresa = NVL(:P116_COD_EMPRESA_PROP, :P116_COD_EMPRESA_SOLICITADO)',
'   and p.ind_empresa_cargo = ''S''',
'   /*',
'   and not exists (select 1 ',
'                    from cargos_ccusto cc ',
'                   where cc.cod_empresa = e.cod_empresa',
'                     and cc.cod_ccusto = NVL(:P116_COD_CCUSTO_PROP, :P116_COD_CCUSTO))',
'   */',
' union ',
'SELECT SUBSTR(c.cod,1,7)||'' - ''||initcap(nome) descricao , cod',
'  from cargos c',
' where c.dt_term_vig_cargo > to_date(sysdate,''dd/mm/rrrr'')',
'   and exists (select 1',
'                 from parametros_recursos_humanos p',
'                where p.cod_empresa = NVL(:P116_COD_EMPRESA_PROP, :P116_COD_EMPRESA_SOLICITADO)',
'                  and p.ind_empresa_cargo = ''N'')',
') x',
' where not exists (select 1',
'                     from cargos_ccusto c ',
'                    where c.cod_empresa =  NVL(:P116_COD_EMPRESA_PROP, :P116_COD_EMPRESA_SOLICITADO)',
'                     and c.cod_cargo = x.cod',
'                  )',
'union',
'select SUBSTR(r.cod,1,7)||'' - ''||initcap(r.nome) descricao , cod',
'  from cargos r, cargos_ccusto c',
' where r.cod = c.cod_cargo',
'   and c.cod_empresa = NVL(:P116_COD_EMPRESA_PROP, :P116_COD_EMPRESA_SOLICITADO)',
'   and c.cod_ccusto = NVL(:P116_COD_CCUSTO_PROP, :P116_COD_CCUSTO)',
'ORDER BY 2'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Selecione -'
,p_lov_cascade_parent_items=>'P116_COD_EMPRESA_PROP,P116_COD_EMPRESA_SOLICITADO,P116_COD_CCUSTO_PROP,P116_COD_CCUSTO'
