wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(785777745666276422)
,p_name=>'P116_COD_LOCAL_PROP_1'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_api.id(284430522150490389402)
,p_prompt=>'Local de Trabalho'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT distinct l.cod_local_trab||'' - ''||initcap(l.DESCRICAO)||',
'case when trim(endereco) is not null then '' | ''||Initcap(endereco) end ||',
'                 case when trim(numero) is not null then '', ''||numero end ||',
'                 case when trim(complemento) is not null then '' - ''||complemento end ||',
'                 case when trim(bairro) is not null then '' - ''||bairro end ||',
'                 case when trim(cidade) is not null then '', ''||cidade end ||',
'                 case when trim(UF) is not null then ''/''||UF end ||',
'                 case when trim(cep) is not null then '' - CEP: ''||lpad(cep,5,''0'')||''-''||lpad(complemento_cep,3,''0'') end',
'descricao, l.cod_local_trab cod',
'      FROM local_trab l, filial_local f',
'     WHERE nvl(L.ATIVO,''S'') = ''S''',
'       AND l.cod_local_trab = f.cod_local_filial',
'       and not exists (select 1 from unid_adm_secao_local u where u.cod_local_trab = l.cod_local_trab)',
'       AND F.COD_EMPRESA = nvl(:P116_COD_EMPRESA_PROP,:P116_COD_EMPRESA_SOLICITADO)',
'       AND F.COD_FILIAL = nvl(:P116_FILIAL_PROP,:P116_COD_FILIAL)',
'UNION',
'SELECT distinct l.cod_local_trab||'' - ''||initcap(l.DESCRICAO)||',
'case when trim(endereco) is not null then '' | ''||Initcap(endereco) end ||',
'                 case when trim(numero) is not null then '', ''||numero end ||',
'                 case when trim(complemento) is not null then '' - ''||complemento end ||',
'                 case when trim(bairro) is not null then '' - ''||bairro end ||',
'                 case when trim(cidade) is not null then '', ''||cidade end ||',
'                 case when trim(UF) is not null then ''/''||UF end ||',
'                 case when trim(cep) is not null then '' - CEP: ''||lpad(cep,5,''0'')||''-''||lpad(complemento_cep,3,''0'') end',
'descricao, l.cod_local_trab cod',
'      FROM local_trab l, unid_adm_secao_local u',
'     WHERE nvl(L.ATIVO,''S'') = ''S''',
'       and l.cod_local_trab = u.cod_local_trab',
'       AND U.COD_EMPRESA = nvl(:P116_COD_EMPRESA_PROP,:P116_COD_EMPRESA_SOLICITADO)',
'       AND U.COD_UNIDADE_ADM = nvl(:P116_UNIDADE_ADM_PROP,:P116_UNIDADE_ADM_1)',
'union',
'SELECT distinct LT.COD_LOCAL_TRAB||'' - ''||initcap(LT.DESCRICAO)||',
'case when trim(endereco) is not null then '' | ''||Initcap(endereco) end ||',
'                 case when trim(numero) is not null then '', ''||numero end ||',
'                 case when trim(complemento) is not null then '' - ''||complemento end ||',
'                 case when trim(bairro) is not null then '' - ''||bairro end ||',
'                 case when trim(cidade) is not null then '', ''||cidade end ||',
'                 case when trim(UF) is not null then ''/''||UF end ||',
'                 case when trim(cep) is not null then '' - CEP: ''||lpad(cep,5,''0'')||''-''||lpad(complemento_cep,3,''0'') end',
'descricao, LT.COD_LOCAL_TRAB codigo',
'FROM   LOCAL_TRAB LT',
'      ,CONFIGURACOES C',
'WHERE nvl(:p116_utiliza_secao,''N'') = ''N''',
'and ((NVL(C.IND_CARGO_LOCAL,''N'') = ''N'')',
'OR      (NVL(C.IND_CARGO_LOCAL,''N'') = ''S''',
'     AND EXISTS (SELECT 1',
'                 FROM   CARGOS_LOCAL_TRAB CLT',
'                 WHERE  SYSDATE BETWEEN CLT.DT_VALIDADE_INICIAL AND NVL(CLT.DT_VALIDADE_FINAL,SYSDATE+1)',
'                 AND    CLT.COD_LOCAL_TRAB = LT.COD_LOCAL_TRAB)))',
'ORDER BY 2'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Selecione -'
,p_lov_cascade_parent_items=>'P116_COD_EMPRESA_PROP,P116_COD_EMPRESA_SOLICITADO,P116_FILIAL_PROP,P116_COD_FILIAL,P116_UNIDADE_ADM_PROP,P116_UNIDADE_ADM_1,P116_UTILIZA_SECAO'
,p_ajax_optimize_refresh=>'N'
,p_cSize=>30
,p_display_when=>'P116_COD_SOLICITACAO'
,p_display_when_type=>'ITEM_IS_NULL'
,p_field_template=>wwv_flow_api.id(281503513276304346679)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_attribute_01=>'DIALOG'
,p_attribute_02=>'FIRST_ROWSET'
,p_attribute_03=>'N'
,p_attribute_04=>'N'
,p_attribute_05=>'N'
);
end;
/
