,p_prompt=>'Grade'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select distinct fx.cod_grupos_salariais||'' - ''||initcap(b.descricao) descricao, fx.cod_grupos_salariais codigo',
'  from categoria_cargo_rel ccr',
'      ,grupos_ponto_faixa fx',
'      ,categoria_grupos_salariais b',
' where fx.cod_cat_grupos_salariais = b.cod_cat_grupos_salariais',
'   and fx.cod_empresa_sindjorn = :P116_COD_EMPRESA_NVL',
'   and fx.cod_sindicato = :P116_SIND_PONTO_DE_FX_NVL',
'   and sysdate between fx.dt_inicio and nvl(fx.dt_fim, sysdate)',
'   --and fx.cod_cat_grupos_salariais = ccr.cod_cat_grupos_salariais',
'   and fx.cod_grupos_salariais = ccr.cod_cat_grupo_sal',
'   and ccr.cod_categoria in (select cv.cod_categoria',
'                             from   cl_vaga cv',
'                             where  cv.cod_filial  = NVL(:P116_FILIAL_PROP,:P116_FILIAL)',
'                             and    cv.cod_empresa = :P116_COD_EMPRESA_NVL',
'                             and    cv.cod_vaga    = :P116_CAD_VAGA_PROP',
'                             union',
'                             select :P116_COD_CATEGORIA from dual',
'                             where  :P116_CARGO_PROP is null)',
'   and ccr.cod_cargo = NVL(:P116_CARGO_PROP,:P116_CARGO)',
' order by 1',
''))
