wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(785794822108276431)
,p_name=>'P116_COD_CAT_GRUPOS_SAL_PROP'
,p_item_sequence=>100
,p_item_plug_id=>wwv_flow_api.id(284430530103679389412)
,p_prompt=>'Categoria de Grade'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT DISTINCT b.cod_cat_grupos_salariais||'' - ''||INITCAP(b.descricao) descricao, ',
'       b.cod_cat_grupos_salariais codigo',
'  FROM grupos_ponto_faixa_aux a, categoria_grupos_salariais b',
' WHERE a.cod_cat_grupos_salariais = b.cod_cat_grupos_salariais',
'   AND a.cod_grupos_salariais = nvl(:p116_grupo_salarial_prop, :p116_grupo_salarial)',
'   AND a.cod_empresa_sindjorn = NVL(:P116_COD_EMPRESA_PROP,:P116_COD_EMPRESA_SOLICITADO)',
'   AND (a.cod_sindicato = :P116_SIND_PONTO_DE_FX_NVL OR',
'       a.cod_sindicato = 999)',
'   AND NVL(:p116_altera_sind_diss, ''N'') = ''N''',
'UNION',
'SELECT DISTINCT  b.cod_cat_grupos_salariais||'' - ''||INITCAP(b.descricao) descricao, ',
'       b.cod_cat_grupos_salariais codigo',
