'WHERE R.COD <> ''NUL''',
' --AND R.COD <> :P116_REG_TRAB',
' AND R.COD_EMPRESA = NVL(:P116_COD_EMPRESA_PROP,:P116_COD_EMPRESA_SOLICITADO)',
' and not exists (select 1 ',
'                   from sind_reg_trabalho x ',
'                  where x.cod_empresa = r.cod_empresa ',
'                    and x.cod_sindicato = nvl(:P116_NOVO_SINDICATO,:P116_NUM_SIND_DISS)',
'                   -- and x.cod_reg_trab = r.cod',
'                )',
' union',
unistr(' Select ''C\00F3digo: ''||R.cod||'' - ''||r.desc_regime descricao_regime, '),
'       R.cod codigo_regime',
'from REG_TRABALHO R, SIND_REG_TRABALHO S',
'WHERE R.COD <> ''NUL''',
' AND R.COD = S.COD_REG_TRAB',
' AND R.COD_EMPRESA = S.COD_EMPRESA',
' AND R.COD_EMPRESA = NVL(:P116_COD_EMPRESA_PROP,:P116_COD_EMPRESA_SOLICITADO)',
' AND S.COD_SINDICATO = nvl(:P116_NOVO_SINDICATO,:P116_NUM_SIND_DISS)',
