wwv_flow_api.create_page_item(
 p_id=>wwv_flow_api.id(785842544199276446)
,p_name=>'P116_CAD_VAGA_PROP'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_api.id(284430564484659389452)
,p_prompt=>unistr('Posi\00E7\00E3o')
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'''Vaga: ''||vg.cod_vaga||'', ''||',
'''Vaga Compartilhada: ''||vg.vaga_comp||'', ''||',
unistr('''Requisi\00E7\00E3o: ''||vg.cod_requisicao||'', ''||'),
'''Empresa: ''||vg.cod_empresa||'', ''||',
'''Filial: ''||vg.cod_filial||'', ''||',
'''C.Custo: ''||vg.cod_ccusto||'' - ''||initcap(fnct_nome_ccusto(vg.cod_empresa, vg.cod_ccusto))||'', ''||',
'''Cargo: ''||vg.cod_cargo||'' - ''||initcap(vg.nome_cargo)||'', ''||',
'''FTE: ''||vg.fte||'', ''||',
'''C.Custo Cont.: ''||vg.cod_ccusto_contab||'', ''||',
unistr('''Unid. de Neg\00F3cio: ''||vg.cod_un_negocio||'', ''||'),
'''Unid. Administrativa: ''||vg.cod_unidade_adm descricao, TO_NUMBER(vg.cod_vaga) codigo',
'FROM   parametros_recursos_humanos prh,',
'  (select distinct ',
'   a.cod_filial,',
'   a.cod_vaga cod_vaga,',
'   decode(a.ind_vaga_compartilhada,''S'',a.vaga_compartilhada,null) vaga_comp,',
'   a.cod_requisicao,',
'   a.cod_ccusto,',
'   c.nome nome_ccusto,',
'   a.cod_cargo, ',
'   b.nome nome_cargo, ',
'   a.coeficiente_fte FTE,',
'   a.cod_empresa,',
'   a.cod_ccusto_contab,',
'   a.cod_un_negocio,',
'   a.cod_unidade_adm',
'   from cl_vaga a,',
'        cargos b,',
'        centro_de_custo c',
'   where a.sit_vaga = ''A''',
'   and b.cod = a.cod_cargo',
'   and c.cod_empresa = a.cod_empresa',
'   and c.cod = a.cod_ccusto',
'   and a.cod_empresa = :p116_emp_vaga_prop',
'   and a.cod_filial = :p116_filial_vaga_prop',
'   and a.disponivel = ''S''',
'   union ',
'   select distinct ',
'          a.cod_filial,',
'          a.cod_vaga cod_vaga,',
'          decode(a.ind_vaga_compartilhada,''S'',a.vaga_compartilhada,null) vaga_comp,',
'          a.cod_requisicao,',
'          a.cod_ccusto,',
'          c.nome nome_ccusto,',
'          a.cod_cargo, ',
'          b.nome nome_cargo,',
'          a.coeficiente_fte FTE,',
'          a.cod_empresa,',
'          a.cod_ccusto_contab,',
'          a.cod_un_negocio,',
'          a.cod_unidade_adm',
'       from cl_vaga a,',
'            cargos b,',
'            centro_de_custo c',
'       where a.sit_vaga = ''A''',
'       and b.cod = a.cod_cargo',
'       and c.cod_empresa = a.cod_empresa',
'       and c.cod = a.cod_ccusto',
'       and a.cod_empresa = :p116_emp_vaga_prop',
'       and a.cod_filial = :p116_filial_vaga_prop',
'       and a.vaga_compartilhada =  :P116_cad_vaga) vg',
' WHERE ((nvl(prh.flag_lista_vaga_completa,''S'') = ''S'')',
' or ((nvl(prh.flag_lista_vaga_completa,''S'') = ''N'')',
' and ((vg.cod_empresa,vg.cod_filial) in (select uof.cd_empresa,uof.cd_filial',
'                                        from usuario_oracle_filiais uof',
'                                        where uof.nm_usuario_oracle = :P_USUARIO))',
'and ((vg.cod_empresa,vg.cod_ccusto) in (select uoc.cod_empresa, uoc.cod_ccusto',
'                                       from usuario_oracle_ccusto uoc',
'                                       where uoc.nm_usuario_oracle = :P_USUARIO))',
'))',
'and prh.cod_empresa = :P_EMPRESA_USER',
'and :p116_ind_vaga_simultanea = ''N''',
'union',
'select ',
'''Vaga: ''||a.cod_vaga||'', ''||',
'''Vaga Compartilhada: ''||decode(a.ind_vaga_compartilhada,''S'',a.vaga_compartilhada,null)||'', ''||',
unistr('''Requisi\00E7\00E3o: ''||a.cod_requisicao||'', ''||'),
'''Empresa: ''||a.cod_empresa||'', ''||',
'''Filial: ''||a.cod_filial||'', ''||',
'''C.Custo: ''||a.cod_ccusto||'' - ''||initcap(fnct_nome_ccusto(a.cod_empresa, a.cod_ccusto))||'', ''||',
'''Cargo: ''||a.cod_cargo||'' - ''||initcap(b.nome)||'', ''||',
'''FTE: ''||a.coeficiente_fte||'', ''||',
'''C.Custo Cont.: ''||a.cod_ccusto_contab||'', ''||',
unistr('''Unid. de Neg\00F3cio: ''||a.cod_un_negocio||'', ''||'),
'''Unid. Administrativa: ''||a.cod_unidade_adm descricao, TO_NUMBER(a.cod_vaga) codigo',
'  from cl_vaga a,',
'       cargos b,',
'       centro_de_custo c,',
'       consulta_requisicoes_2 e',
' where EXISTS (SELECT ''S''',
'              FROM informacoes_funcionais_cad c',
'             WHERE c.cod_empresa = a.cod_empresa',
'               AND c.cad_vaga = a.cod_vaga',
'               AND c.filial = a.cod_filial',
'               AND c.situacao = ''01'')',
'   and a.sit_vaga = ''A''',
'   and b.cod = a.cod_cargo',
'   and c.cod_empresa = a.cod_empresa',
'   and c.cod = a.cod_ccusto',
unistr('   and Nvl(e.aprovado, ''N\00C3O'') = ''SIM'''),
'   and a.cod_filial = e.filial',
'   and b.cod = :P116_cargo',
'   and :p116_ind_vaga_simultanea = ''S''',
'order by 2'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Selecione -'
,p_lov_cascade_parent_items=>'P116_EMP_VAGA_PROP,P116_FILIAL_VAGA_PROP,P116_CAD_VAGA,P_USUARIO,P_EMPRESA_USER,P116_IND_VAGA_SIMULTANEA,P116_CARGO'
,p_ajax_optimize_refresh=>'Y'
