'',
'begin',
'',
'if (:P116_SALARIO_PROP is not null OR :P116_REMUNERACAO_VARIAVEL_PROP IS NOT NULL) and :P116_DT_SALARIO_PROP is null AND :P116_COD_EMPRESA_PROP IS NULL then',
