'                                       ,:p116_ccusto_vaga_prop',
'                                       ,:p116_cargo_vaga_prop',
'                                       ,:p116_cod_categoria',
'                                       ,:p116_cod_categoria_prop',
'                                       ,:p116_dt_cargo_prop',
