wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(785893797746276462)
,p_validation_name=>unistr('(Hor\00E1rio) Valida dt_vigencia')
,p_validation_sequence=>350
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  v_flg_retorno varchar2(3);',
'  v_msg_retorno varchar2(4000);',
'  vsaida_erro   exception;',
'begin',
'',
'  if :p116_cad_vaga_prop is null then',
'    for x in (select iff.dt_horario',
'              from   informacoes_funcionais_cad iff',
'              where  iff.matricula    = :P116_MAT_SOLICITADO',
'              and    iff.cod_empresa  = :P116_COD_EMPRESA_SOLICITADO) loop',
'      if :P116_dt_horario_prop <= x.dt_horario then',
unistr('        v_msg_retorno := ''A data informada n\00E3o deve ser anterior ou igual \00E0 data da \00FAltima mudan\00E7a de situa\00E7\00E3o: ''||to_char(x.dt_horario, ''dd/mm/rrrr'') || ''.'';'),
'        raise vsaida_erro;',
'      end if;',
'    end loop;',
'    -- CH39460',
'    if :P116_COD_HORARIO_PROP is not null and :P116_DT_HORARIO_PROP is null then ',
unistr('      return (''O Campo de Data Hor\00E1rio deve ser preenchido!'');'),
'    end if;',
'    v_msg_retorno := null;',
'    Pkg_Alt_Func.Valida_Dt_Horario_Prop(:p116_cod_empresa_solicitado',
'                                     ,:p116_mat_solicitado',
'                                     ,:p116_dt_admissao',
'                                     ,:p116_dt_horario_prop',
'                                     ,v_flg_retorno',
'                                     ,v_msg_retorno);',
'    if trim(v_msg_retorno) is not null and v_flg_retorno = ''N'' then',
'      raise vsaida_erro;',
'    end if;',
'  end if;',
'exception',
'  when vsaida_erro then',
'    return v_msg_retorno;',
'end;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_associated_item=>wwv_flow_api.id(785752853406276414)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
