wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(785926273766276471)
,p_validation_name=>'Possui Saldo'
,p_validation_sequence=>500
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'/*',
'cursor c1 is',
'select ''S'' existe',
'  from REQ_BENEFICIOS_ITENS_TEMP r',
' where R.cod_empresa = nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'   and R.matricula = :p116_mat_solicitado;*/',
'--v_c1 c1%rowtype;   ',
'',
'v_flg_retorno  varchar2(3);',
'v_msg_retorno  varchar2(4000);',
'V_SALDO        NUMBER;-- := :P116_SALDO;',
'V_ERRO         VARCHAR2(4000);',
'v_vlr_Req      number := 0;',
'v_vlr_Remu     number := 0;',
'v_vlr_restante number := 0;',
'',
'begin',
'EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= '''',.'''' '';',
'',
'/*',
'open c1;',
'fetch c1 into v_c1;',
'close c1;*/',
'',
'',
'      select  sum(nvl(r.quantidade,1)*r.valor) valor_total',
'       ,   :P116_REMUNERACAO_VARIAVEL_PROP',
'	   ,   (:P116_REMUNERACAO_VARIAVEL_PROP - sum(nvl(r.quantidade,1)*r.valor)) RESTANTE',
'       into v_vlr_Req',
'         ,  v_vlr_Remu',
'		 ,  v_vlr_restante',
'     from REQ_BENEFICIOS_ITENS_TEMP R, BENEFICIOS_FAMILIA B, BENEFICIOS_FAMILIA_TIPO T',
'    where r.cod_empresa = b.cod_empresa',
'      and r.cod_empresa = t.cod_empresa',
'      and r.cod_familia = b.cod_familia',
'      and r.cod_familia = t.cod_familia',
'      and r.tipo_cod_familia = t.tipo_cod_familia',
'      and R.cod_empresa = nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'      and R.matricula = :p116_mat_solicitado',
'      AND nvl(R.OPERACAO,''Z'') <> ''D'';',
'',
'V_SALDO := to_number(:p116_saldo);',
'',
'',
'if nvl(v_vlr_Req,0) <> nvl(v_vlr_Remu,0) and nvl(v_vlr_restante,0) > 0 then ',
'  V_FLG_RETORNO := ''N'';',
unistr('  V_MSG_RETORNO := ''Ainda existe um saldo de ''||nvl(v_vlr_restante,0)||'' para ser distribu\00EDdo entre os benef\00EDcios!'';'),
' ELSIF NVL(v_vlr_restante,0) < 0 THEN',
'    V_FLG_RETORNO := ''N'';',
unistr('    V_MSG_RETORNO := ''O saldo est\00E1 negativo!'';'),
'  ELSIF NVL(V_SALDO,0) > 0 THEN',
'    V_FLG_RETORNO := ''N'';',
unistr('    V_MSG_RETORNO := ''Ainda existe um saldo de ''||nvl(v_saldo,0)||'' para ser distribu\00EDdo entre os benef\00EDcios!'';'),
'end if;',
'',
'',
'IF V_MSG_RETORNO IS NOT NULL THEN',
unistr(' return ''Valida\00E7\00E3o de Benef\00EDcios: ''||v_msg_retorno;'),
'END IF;',
'',
'/*',
'if (:P116_REQ_BENEFICIOS = ''S'' or nvl(:P116_REMUNERACAO_VARIAVEL_PROP,0) > 0) and nvl(:p116_req_beneficios,''N'') = ''S'' then--nvl(v_c1.existe,''N'') = ''S'' then',
'',
'',
'--pkg_req_beneficio.valida_saldo(:p116_saldo, ''CREATE'', v_flg_retorno, v_msg_retorno);',
'',
' IF NVL(V_SALDO,0) > 0 THEN',
'    V_FLG_RETORNO := ''N'';',
unistr('    V_MSG_RETORNO := ''Ainda existe um saldo de ''||nvl(v_saldo,0)||'' para ser distribu\00EDdo entre os benef\00EDcios!'';'),
' ELSIF NVL(V_SALDO,0) < 0 THEN',
'    V_FLG_RETORNO := ''N'';',
unistr('    V_MSG_RETORNO := ''O saldo est\00E1 negativo!'';'),
' END IF;',
' --v_ponto := 4;',
' if trim(v_msg_retorno) is not null then',
unistr('    return ''2 - Valida\00E7\00E3o de Benef\00EDcios: ''||trim(v_msg_retorno);'),
' end if;',
' --v_ponto := 5;',
'end if;',
'-- v_ponto := 6;',
'if :P116_REQ_BENEFICIOS = ''S'' and nvl(v_c1.existe,''N'') = ''S'' then',
' if nvl(:p116_saldo,0) > 0 then',
unistr('    return ''3 - Valida\00E7\00E3o de Benef\00EDcios: Ainda existe um saldo de ''||to_number(:p116_saldo)||'' para ser distribu\00EDdo.'';'),
' end if;',
'end if;',
' --v_ponto := 7;',
'',
'EXCEPTION',
'WHEN OTHERS THEN',
'V_ERRO := SQLERRM;',
'--return v_ponto||'' Erro ao Validar Saldo1: ''||V_SALDO||'' - ''||to_number(nvl(:p116_saldo,10))||'' - Erro> ''||v_erro;',
'--RAISE_APPLICATION_ERROR (-20001, v_ponto||'' Erro ao Validar Saldo: ''||v_erro);',
'*/',
'',
'end;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'VOLTAR'
,p_validation_condition_type=>'REQUEST_NOT_EQUAL_CONDITION'
,p_associated_item=>wwv_flow_api.id(785736984061276408)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
