'v_c1 c1%rowtype;',
'',
'begin',
'',
'if :p116_rowid is null then ',
'',
'    pkg_alt_func.Valida_Key_Commit2(:p116_cod_empresa_solicitado',
'                                   ,:p116_cod_solicitacao',
