wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(785905838666276465)
,p_validation_name=>unistr('Valida Benef\00EDcios')
,p_validation_sequence=>660
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'   select DISTINCT R.COD_EMPRESA, ',
'                   R.MATRICULA, ',
'                   R.COD_FAMILIA, ',
'                   initcap(B.DESCRICAO_FAMILIA) BENEFICIO, ',
'                   R.TIPO_COD_FAMILIA, ',
'                   initcap(T.DESCRICAO_TIPO) TIPO_BENEFICIO, ',
'                   R.VALOR_TIPO VALOR_MINIMO, ',
'                   R.VALOR_TETO VALOR_MAXIMO,',
'                   R.VALOR valor_escolhido, ',
'                   r.quantidade, ',
'                   nvl(r.quantidade,1)*r.valor valor_total',
'     from REQ_BENEFICIOS_ITENS_TEMP R, BENEFICIOS_FAMILIA B, BENEFICIOS_FAMILIA_TIPO T',
'    where r.cod_empresa = b.cod_empresa',
'      and r.cod_empresa = t.cod_empresa',
'      and r.cod_familia = b.cod_familia',
'      and r.cod_familia = t.cod_familia',
'      and r.tipo_cod_familia = t.tipo_cod_familia',
'      and R.cod_empresa = :p116_cod_empresa_solicitado',
'      and R.matricula = :p116_mat_solicitado',
'      AND nvl(R.OPERACAO,''Z'') = ''I'';',
'',
'v_c1 c1%rowtype;',
'',
'v_valor_min number;',
'v_valor_max number;',
'v_valor number;',
'v_quantidade number;',
'v_total number;',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'cursor c2 is',
'select ''S'' existe',
'  from REQ_BENEFICIOS_ITENS_TEMP r',
' where R.cod_empresa = :p116_cod_empresa_solicitado',
'   and R.matricula = :p116_mat_solicitado;',
'   ',
'v_c2 c2%rowtype;',
'',
'begin',
'',
'open c2;',
'fetch c2 into v_c2;',
'close c2;',
'',
'if :P116_REMUNERACAO_VARIAVEL_PROP is not null and nvl(v_c2.existe,''N'') = ''S'' then',
'',
'for l1 in c1',
'loop',
'pkg_req_beneficio.Popula_Valor (nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado),',
'                        :p116_mat_solicitado,',
'                        l1.cod_familia,',
'                        l1.tipo_cod_familia,',
'                        v_valor_min,',
'                        v_valor_max,',
'                        v_valor,',
'                        v_quantidade,',
'                        nvl(:P116_SALARIO_PROP,nvl(:P116_SALARIO_1,:p116_salario)),',
'                        nvl(:P116_REMUNERACAO_VARIAVEL_PROP,:P116_REMUNERACAO_VARIAVEL));',
'',
'v_total := (nvl(v_valor,0) * nvl(v_quantidade,1));',
'',
'pkg_req_beneficio.valida_valor(l1.valor_escolhido, v_quantidade, v_valor_min, v_valor_max, 10000000, v_flg_retorno, v_msg_retorno);',
'',
'if v_flg_retorno = ''N'' then',
unistr('return ''4 - Valida\00E7\00E3o de Benef\00EDcios: ''||l1.BENEFICIO||'' - ''||l1.TIPO_BENEFICIO||'' - ''||v_msg_retorno;'),
'end if;',
'',
'v_valor_min := null;',
'v_valor_max := null;',
'v_valor := null;',
'v_quantidade := null;',
'v_total := null;',
'v_flg_retorno := null;',
'v_msg_retorno := null;',
'',
'end loop;',
'',
'end if;',
'',
'end;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
