'select cod_sit_solicitacao',
'  from solicitacao_alteracao_func',
' where cod_solicitacao = :P116_COD_SOLICITACAO',
'   and cod_empresa_solicitado = :p116_cod_empresa_solicitado;',
'   ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
'IF v_c1.cod_sit_solicitacao IS NOT NULL THEN',
'',
'    if v_c1.cod_sit_solicitacao in (1,5) and :P116_COD_SIT_SOLICITACAO in (1,3,6) then',
'       v_flg_retorno := ''S'';',
'       v_msg_retorno := null;',
'    elsif v_c1.cod_sit_solicitacao = 1 and :P116_COD_SIT_SOLICITACAO in (2,4,5) then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''N\00E3o \00E9 permitido alterar para a situa\00E7\00E3o escolhida.'';'),
'    elsif v_c1.cod_sit_solicitacao = 5 and :P116_COD_SIT_SOLICITACAO in (1,2,4) then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''N\00E3o \00E9 permitido alterar para a situa\00E7\00E3o escolhida.'';'),
'    elsif v_c1.cod_sit_solicitacao = 6 and :P116_COD_SIT_SOLICITACAO in (1,3) then',
'       v_flg_retorno := ''S'';',
'       v_msg_retorno := null;',
'    elsif v_c1.cod_sit_solicitacao = 6 and :P116_COD_SIT_SOLICITACAO not in (1,3) then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''N\00E3o \00E9 permitido alterar para a situa\00E7\00E3o escolhida.'';'),
'    elsif v_c1.cod_sit_solicitacao in (2,3,4) and :P116_COD_SIT_SOLICITACAO <> v_c1.cod_sit_solicitacao then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''N\00E3o \00E9 permitido alterar a situa\00E7\00E3o desta requisi\00E7\00E3o.'';'),
'    elsif :P116_COD_SIT_SOLICITACAO = v_c1.cod_sit_solicitacao then',
'       v_flg_retorno := ''S'';',
'       v_msg_retorno := null;',
'    end if;',
'    ',
' if trim(v_msg_retorno) is not null and v_flg_retorno = ''N'' then',
'    return v_msg_retorno;',
' end if;',
' ',
'END IF;',
' ',
'end;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_api.id(785889825781276458)
,p_associated_item=>wwv_flow_api.id(785883912627276457)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
end;
