,p_validation_name=>unistr('Valida altera\00E7\00E3o de sal\00E1rio para parcelamento')
,p_validation_sequence=>740
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  VPARCELAS VARCHAR2(15);',
'  VMSG VARCHAR2(400);',
'BEGIN',
'  FOR X IN (SELECT COD_PARCELA FROM SOLIC_APROV_PARC_SALARIO P WHERE P.EFETIVACAO = ''S'' AND P.COD_SOLICITACAO = :P116_COD_SOLICITACAO ORDER BY 1) LOOP',
'    IF LENGTH(VPARCELAS) > 1 THEN',
'      VPARCELAS := VPARCELAS||'', ''||X.COD_PARCELA;',
'    ELSE',
'      VPARCELAS := X.COD_PARCELA;',
'    END IF;',
'  END LOOP;',
'  IF VPARCELAS IS NOT NULL THEN',
'    IF LENGTH(VPARCELAS) > 1 THEN',
unistr('      Vmsg := ''As parcelas ''||VPARCELAS||'' j\00E1 foram efetivadas. N\00E2o \00E9 poss\00EDvel alterar o sal\00E1rio proposto!'';'),
'    ELSE',
unistr('      VMSG := ''A parcela ''||VPARCELAS||'' j\00E1 foi efetivada. N\00E3o \00E9 poss\00EDvel alterar o sal\00E1rio proposto!'';'),
'    END IF;',
'    RETURN(VMSG);',
'  END IF;',
'END;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_associated_item=>wwv_flow_api.id(785796823796276432)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
