wwv_flow_api.create_page_validation(
 p_id=>wwv_flow_api.id(785898236402276463)
,p_validation_name=>'Valida Remuneracao e Beneficio'
,p_validation_sequence=>780
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'   cursor c1 is',
'   select sum(nvl(r.quantidade,1)*r.valor) total_benef ',
'     from REQ_BENEFICIOS_ITENS_TEMP R, BENEFICIOS_FAMILIA B, BENEFICIOS_FAMILIA_TIPO T',
'    where r.cod_empresa = b.cod_empresa',
'      and r.cod_empresa = t.cod_empresa',
'      and r.cod_familia = b.cod_familia',
'      and r.cod_familia = t.cod_familia',
'      and r.tipo_cod_familia = t.tipo_cod_familia',
'      and R.cod_empresa = nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'      and R.matricula = :p116_mat_solicitado',
'      AND nvl(R.OPERACAO,''I'') = ''I'';',
'      ',
'    v_c1 c1%rowtype;',
'    ',
'    cursor c2 is',
'    select sum((nvl(i.quantidade,1)*i.valor)) total_benef',
'      from beneficios_familia b, beneficios_familia_tipo t, beneficios_fam_tipo_vlr v, req_beneficios_itens i',
'     where b.cod_empresa = t.cod_empresa',
'       and b.cod_empresa = v.cod_empresa',
'       and b.cod_familia = i.cod_familia',
'       and b.cod_familia = t.cod_familia',
'       and b.cod_familia = v.cod_familia',
'       and t.tipo_cod_familia = v.tipo_cod_familia',
'       and t.tipo_cod_familia = i.tipo_cod_familia',
'       and b.cod_empresa = nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'       and :p116_dt_solicitacao between b.dt_inicio_familia and nvl(b.dt_fim_familia,sysdate)',
'       and :p116_dt_solicitacao between t.dt_inicio_tipo and nvl(t.dt_fim_tipo,sysdate)',
'       and :p116_dt_solicitacao between v.dt_inicio_valor and nvl(v.dt_fim_valor,sysdate)',
'       and i.cod_req_alt_func = :p116_cod_solicitacao',
'       AND v.desconta_saldo = ''S''',
'       and nvl(i.operacao,''I'') = ''I'';',
'',
'    v_c2 c2%rowtype;',
'',
'begin',
'',
' if :p116_cod_solicitacao is not null then',
'',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'    ',
'    open c2;',
'    fetch c2 into v_c2;',
'    close c2;',
'',
'    if nvl(v_c1.total_benef,0) > 0 and (nvl(v_c1.total_benef,0) <> nvl(:P116_REMUNERACAO_VARIAVEL_PROP,0)) then',
unistr('       return ''Refa\00E7a a distribui\00E7\00E3o de benef\00EDcios! A soma da distribui\00E7\00E3o dos Valores de Benef\00EDcios n\00E3o equivale ao Valor da Remunera\00E7\00E3o Vari\00E1vel Proposta.'';'),
'    end if;',
'    ',
'    if nvl(v_c2.total_benef,0) > 0 and (nvl(v_c2.total_benef,0) <> nvl(:P116_REMUNERACAO_VARIAVEL_PROP,0)) then',
unistr('       return ''Refa\00E7a a distribui\00E7\00E3o de benef\00EDcios! A soma da distribui\00E7\00E3o dos Valores de Benef\00EDcios n\00E3o equivale ao Valor da Remunera\00E7\00E3o Vari\00E1vel Proposta.'';'),
'    end if;',
'    ',
' end if;',
'',
'end;'))
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'SAVEX'
,p_validation_condition_type=>'REQUEST_EQUALS_CONDITION'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
