,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    ',
'CURSOR C1 IS',
'SELECT DISTINCT b.COD_CAT_GRUPOS_SALARIAIS codigo, ',
'       a.cod_sindicato,',
'       a.rt_jornada_mensal',
'FROM  grupos_ponto_faixa_aux a, categoria_grupos_salariais b ',
'WHERE a.cod_cat_grupos_salariais = b.cod_cat_grupos_salariais',
'AND a.cod_grupos_salariais       = :P116_GRUPO_SALARIAL_PROP',
'AND a.cod_empresa_sindjorn       = NVL(:P116_COD_EMPRESA_PROP,:P116_COD_EMPRESA_SOLICITADO)',
'and (a.cod_sindicato = :P116_NUM_SIND_DISS or a.cod_sindicato = 999)',
'ORDER BY 1;',
'',
'V_C1 C1%ROWTYPE;',
'',
'BEGIN',
'    ',
'OPEN  C1;',
'FETCH C1 INTO V_C1;',
'CLOSE C1;    ',
'    ',
'IF V_C1.CODIGO IS NOT NULL THEN',
'',
'    :P116_SIND_PONTO_DE_FX_PROP := V_C1.COD_SINDICATO;',
'    :P116_JORN_PONTO_DE_FX_PROP := V_C1.RT_JORNADA_MENSAL;',
'',
'ELSE',
'    null;',
'END IF;    ',
'',
'END;'))
