'if nvl(v_salario_prop,0) + nvl(v_remuneracao_variavel_prop,0) > nvl(v_total_remuneracao_prop,0) and v_total_remuneracao_prop is not null then v_flg_retorno := ''N'';',
unistr(' v_msg_retorno := ''A somat\00F3ria do sal\00E1rio com a remunera\00E7\00E3o vari\00E1vel n\00E3o pode ser maior que o total da remunera\00E7\00E3o.'';'),
'end if;',
'                                             ',
' if trim(v_msg_retorno) is not null then',
'    :P116_ITEM_VALIDACAO := TRIM(UPPER(''p116_salario_prop_3''));',
'    :p116_ok       := ''N'';',
