wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(785979714156276487)
,p_event_id=>wwv_flow_api.id(785979250572276487)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select a.cod_empresa,',
'a.cod_filial,',
'a.cod_ccusto,',
'a.cod_cargo,',
'a.cod_funcao,',
'a.cod_ccusto_contab,',
'a.cod_un_negocio,',
'a.cod_unidade_adm,',
'a.cod_local_trab,',
'a.remuneracao,',
'a.cod_atividade,',
'a.cod_horario',
'  from cl_vaga                a',
' where a.cod_vaga = :p116_cad_vaga_prop',
'   and a.cod_empresa = :p116_emp_vaga_prop',
'   and a.cod_filial = :p116_filial_vaga_prop;',
' ',
'v_c1 c1%rowtype;',
'',
'cursor c2 is',
'select a.cod_empresa,',
'a.filial cod_filial,',
'a.cod_ccusto,',
'a.cargo cod_cargo,',
'a.funcao cod_funcao,',
'c.cod_ccusto_cont cod_ccusto_contab,',
'(select u.cod_un_negocio from unidade_de_negocio u where rownum = 1 and a.cod_empresa = nvl(u.cod_empresa, a.cod_empresa) and c.cod_ccusto_cont = u.cod_ccusto_contab) cod_un_negocio,',
'a.unidade_adm cod_unidade_adm,',
'a.cod_localizacao cod_local_trab,',
'a.salario,',
'a.cod_atividade,',
'a.cod_horario',
'  from informacoes_funcionais_cad a, centro_de_custo c',
' where a.cod_empresa = c.cod_empresa',
'--   and a.cod_empresa = nvl(u.cod_empresa, a.cod_empresa) ',
'   and a.cod_ccusto = c.cod',
'--   and c.cod_ccusto_cont = u.cod_ccusto_contab (+)',
'   and a.cod_empresa = :p116_cod_empresa_solicitado',
'   and a.matricula = :p116_mat_solicitado;',
'   ',
'v_c2 c2%rowtype;',
'',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
' ',
' open c2;',
' fetch c2 into v_c2;',
' close c2;',
' ',
' if v_c1.cod_empresa <> v_c2.cod_empresa then',
'   :p116_dt_empresa_prop := :p116_dt_vigencia;',
' else ',
'   :p116_dt_empresa_prop := null;',
' end if;',
' ',
' if v_c1.cod_filial <> v_c2.cod_filial then',
'   :p116_dt_filial_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_filial_prop := null;',
' end if;',
' ',
' if v_c1.cod_ccusto <> nvl(:p116_cod_ccusto,v_c2.cod_ccusto) then',
'   :p116_dt_ccusto_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_ccusto_prop := null;',
' end if;',
' ',
' if v_c1.cod_cargo <> v_c2.cod_cargo then',
'   :p116_dt_cargo_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_cargo_prop := null;',
' end if;',
' ',
' if v_c1.cod_funcao <> v_c2.cod_funcao then',
'   :p116_dt_funcao_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_funcao_prop := null;',
' end if;',
' ',
' if v_c1.cod_ccusto_contab <> v_c2.cod_ccusto_contab then',
'   :p116_dt_ccusto_contab := :p116_dt_vigencia;',
' else',
'   :p116_dt_ccusto_contab := null;',
' end if;',
' ',
' if v_c1.cod_unidade_adm <> nvl(:p116_unidade_adm,v_c2.cod_unidade_adm) then',
'   :p116_dt_unid_adm_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_unid_adm_prop := null;',
' end if;',
'',
' if v_c1.cod_local_trab <> v_c2.cod_local_trab then',
'   :P116_DT_LOCAL_PROP := :p116_dt_vigencia;',
' else',
'   :P116_DT_LOCAL_PROP  := null;',
' end if;',
' ',
' if nvl(v_c1.remuneracao,0) <> nvl(v_c2.salario,0) then',
'   :P116_DT_SALARIO_PROP := :p116_dt_vigencia;',
' else',
'   :P116_DT_SALARIO_PROP  := null;',
' end if;',
'',
' if v_c1.cod_atividade <> nvl(:p116_cod_atividade,v_c2.cod_atividade) then',
'   :P116_DT_ATIVIDADE_PROP := :p116_dt_vigencia;',
' else',
'   :P116_DT_ATIVIDADE_PROP  := null;',
' end if;',
'',
' if v_c1.cod_horario <> v_c2.cod_horario then',
'   :P116_DT_HORARIO_PROP := :p116_dt_vigencia;',
' else',
'   :P116_DT_HORARIO_PROP  := null;',
' end if;',
'',
'end;'))
,p_attribute_02=>'P116_CAD_VAGA_PROP,P116_EMP_VAGA_PROP,P116_FILIAL_VAGA_PROP,P116_COD_EMPRESA_SOLICITADO,P116_MAT_SOLICITADO,P116_DT_VIGENCIA,P116_COD_CCUSTO,P116_COD_ATIVIDADE,P116_UNIDADE_ADM'
,p_attribute_03=>'P116_DT_EMPRESA_PROP,P116_DT_FILIAL_PROP,P116_DT_CCUSTO_PROP,P116_DT_CARGO_PROP,P116_DT_FUNCAO_PROP,P116_DT_CCUSTO_CONTAB,P116_DT_UNID_ADM_PROP,P116_DT_LOCAL_PROP,P116_DT_SALARIO_PROP,P116_DT_ATIVIDADE_PROP,P116_DT_HORARIO_PROP'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
,p_da_action_comment=>'--*adv'
);
