,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'v_seq number;',
'v_proposta number;',
'',
'v_item_validacao varchar2(200) := :P116_ITEM_VALIDACAO;',
'',
'begin',
'',
'     pkg_alt_func.Pre_Insert(:p116_cod_empresa_solicitado',
'                           ,:p116_mat_solicitado',
'                           ,:p116_cod_empresa_prop',
'                           ,:p116_dt_empresa_prop',
'                           ,:p116_filial_prop',
'                           ,:p116_dt_filial_prop',
'                           ,:p116_mot_alt_filial_prop',
'                           ,:p116_filial_emprest_prop',
'                           ,:p116_dt_ini_fil_emprest_prop',
'                           ,:p116_mot_alt_fil_emprest_prop',
'                           ,:p116_cad_vaga_prop',
'                           ,:p116_cod_depto_prop',
'                           ,:p116_dt_depto_prop',
'                           ,:p116_mot_alt_depto_prop',
'                           ,:p116_cod_local_prop',
'                           ,:p116_situacao_prop',
'                           ,:p116_situacao_prop_2',
'                           ,:p116_dt_situacao_prop',
'                           ,:p116_dt_situacao_prop_2',
'                           ,:p116_mot_alt_situacao_prop',
'                           ,:p116_mot_alt_situacao_prop_2',
'                           ,:p116_salario_prop',
'                           ,:p116_dt_salario_prop',
'                           ,:p116_mot_alt_sal_prop',
'                           ,:p116_cod_ccusto_prop',
'                           ,:p116_dt_ccusto_prop',
'                           ,:p116_mot_alt_centro_prop',
'                           ,:p116_cargo_prop',
'                           ,:p116_dt_cargo_prop',
'                           ,:p116_mot_alt_cargo_prop',
'                           ,:p116_funcao_prop',
'                           ,:p116_dt_funcao_prop',
'                           ,:p116_mot_alt_funcao_prop',
'                           ,:p116_reg_trab_prop',
'                           ,:p116_dt_reg_trab_prop',
'                           ,:p116_mot_alt_reg_trab_prop',
'                           ,:p116_cod_ccusto_contab',
'                           ,:p116_dt_local_prop',
'                           ,:p116_novo_sindicato',
'                           ,:p116_cod_horario_prop',
'                           ,:p116_dt_horario_prop',
'                           ,:p116_mot_alt_horario_prop',
'                           ,:p116_sindicato_cate_prop',
'                           ,:p116_altera_sind_diss',
'                           ,:p116_parc_salario',
'                           ,:p116_dt_unid_adm_prop',
'                           ,:p116_dt_atividade_prop',
'                           ,:p116_dt_ccusto_contab',
'                           ,:p116_dt_sindicato_cate_prop',
'                           ,v_flg_retorno',
'                           ,v_msg_retorno);',
'',
'if trim(v_msg_retorno) is not null then',
'',
'    if v_flg_retorno = ''N'' then',
'',
'        :P116_ok       := ''N'';',
'        :P116_ITEM_VALIDACAO := TRIM(UPPER(''Pre_Insert''));',
'',
