'    :p116_mensagem := null;',
'    if v_item_validacao = TRIM(UPPER(''p116_cod_categoria_prop'')) OR v_item_validacao IS NULL then',
'       :P116_OK := ''S'';',
'       :P116_ITEM_VALIDACAO := null;',
