,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select a.cod_empresa,',
'a.cod_filial,',
'a.cod_ccusto,',
'a.cod_cargo,',
'a.cod_ccusto_contab,',
'a.cod_un_negocio,',
'a.cod_unidade_adm,',
'a.cod_unidade_adm||'' - ''||initcap(fnct_nome_unidade_adm(a.cod_empresa, a.cod_filial, a.cod_unidade_adm)) unidade_adm,',
'a.cod_categoria,',
'a.Cod_Funcao,',
'a.cod_local_trab',
'  from cl_vaga a',
' where a.cod_vaga = :p116_cad_vaga_prop',
'   and a.cod_empresa = :p116_emp_vaga_prop',
'   and a.cod_filial = :p116_filial_vaga_prop;',
'',
'v_c1 c1%rowtype;',
'',
'cursor c2 is',
'select a.cod_empresa,',
'a.filial cod_filial,',
'a.cod_ccusto,',
'a.cargo cod_cargo,',
'c.cod_ccusto_cont cod_ccusto_contab,',
'u.cod_un_negocio,',
'a.unidade_adm cod_unidade_adm,',
'a.cod_categoria,',
'a.funcao cod_funcao,',
'a.cod_localizacao cod_local_trab',
'  from informacoes_funcionais_cad a, centro_de_custo c, unidade_de_negocio u',
' where a.cod_empresa = c.cod_empresa',
'   and a.cod_empresa = nvl(u.cod_empresa, a.cod_empresa) ',
'   and a.cod_ccusto = c.cod',
'   and c.cod_ccusto_cont = u.cod_ccusto_contab (+)',
'   and a.cod_empresa = :p116_cod_empresa_solicitado',
'   and a.matricula = :p116_mat_solicitado;',
'   ',
'v_c2 c2%rowtype;',
'',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
' open c2;',
' fetch c2 into v_c2;',
' close c2;',
'',
' if (v_c1.cod_unidade_adm <> v_c2.cod_unidade_adm) or v_c1.cod_empresa is null then',
'   :p116_unidade_adm_prop_1 := v_c1.unidade_adm;',
' else',
'   :p116_unidade_adm_prop_1 := null;',
' end if;',
' ',
' if (v_c1.cod_local_trab <> v_c2.cod_local_trab) or v_c1.cod_empresa is null then',
'   :p116_cod_local_prop := v_c1.cod_local_trab;',
' else',
'   :p116_cod_local_prop := null;',
' end if;',
'  ',
'end;'))
,p_attribute_02=>'P116_CAD_VAGA_PROP,P116_EMP_VAGA_PROP,P116_FILIAL_VAGA_PROP,P116_COD_EMPRESA_SOLICITADO,P116_MAT_SOLICITADO'
,p_attribute_03=>'P116_UNIDADE_ADM_PROP_1,P116_COD_LOCAL_PROP'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
