wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(786161164437276525)
,p_event_id=>wwv_flow_api.id(786160597581276525)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'v_item_validacao varchar2(100) := :P116_ITEM_VALIDACAO;',
'',
'cursor c1 is',
'select cod_sit_solicitacao',
'  from solicitacao_alteracao_func',
' where cod_solicitacao = :P116_COD_SOLICITACAO',
'   and cod_empresa_solicitado = :p116_cod_empresa_solicitado;',
'   ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
':p116_mensagem := null;',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
'IF v_c1.cod_sit_solicitacao IS NOT NULL THEN',
'',
'    if v_c1.cod_sit_solicitacao in (1,5) and :P116_COD_SIT_SOLICITACAO in (1,3,6) then',
'       v_flg_retorno := ''S'';',
'       v_msg_retorno := null;',
'    elsif v_c1.cod_sit_solicitacao = 1 and :P116_COD_SIT_SOLICITACAO in (2,4,5) then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''N\00E3o \00E9 permitido alterar para a situa\00E7\00E3o escolhida.'';'),
'    elsif v_c1.cod_sit_solicitacao = 5 and :P116_COD_SIT_SOLICITACAO in (1,2,4) then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''N\00E3o \00E9 permitido alterar para a situa\00E7\00E3o escolhida.'';'),
'    elsif v_c1.cod_sit_solicitacao = 6 and :P116_COD_SIT_SOLICITACAO in (1,3) then',
'       v_flg_retorno := ''S'';',
'       v_msg_retorno := null;',
'    elsif v_c1.cod_sit_solicitacao = 6 and :P116_COD_SIT_SOLICITACAO not in (1,3) then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''N\00E3o \00E9 permitido alterar para a situa\00E7\00E3o escolhida.'';'),
'    elsif v_c1.cod_sit_solicitacao in (2,3,4) and :P116_COD_SIT_SOLICITACAO <> v_c1.cod_sit_solicitacao then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''N\00E3o \00E9 permitido alterar a situa\00E7\00E3o desta requisi\00E7\00E3o.'';'),
'    elsif :P116_COD_SIT_SOLICITACAO = v_c1.cod_sit_solicitacao then',
'       v_flg_retorno := ''S'';',
'       v_msg_retorno := null;',
'    end if;',
'    ',
'    ',
' if trim(v_msg_retorno) is not null then',
'    :P116_ITEM_VALIDACAO := TRIM(UPPER(''P116_COD_SIT_SOLICITACAO''));',
'    :p116_ok       := ''N'';',
'    :p116_flag     := v_flg_retorno;',
'    :p116_mensagem := v_msg_retorno;',
' else',
'    :p116_flag     := null;',
'    :p116_mensagem := null;',
'    if v_item_validacao = TRIM(UPPER(''P116_COD_SIT_SOLICITACAO'')) OR v_item_validacao IS NULL then',
'       :P116_OK := ''S'';',
'       :P116_ITEM_VALIDACAO := null;',
'    else',
'       :P116_ITEM_VALIDACAO := v_item_validacao;',
'    end if;',
' end if;',
' ',
'END IF;',
' ',
'end;'))
,p_attribute_02=>'P116_COD_SOLICITACAO,P116_COD_EMPRESA_SOLICITADO,P116_ITEM_VALIDACAO,P116_COD_SIT_SOLICITACAO'
,p_attribute_03=>'P116_ITEM_VALIDACAO,P116_MENSAGEM,P116_OK,P116_FLAG'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
