,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  VSINDICATO_CATE_PROP SOLICITACAO_PROPOSTAS.SINDICATO_CATE_PROP%TYPE;',
'BEGIN',
'  --',
'  BEGIN',
'	  --',
'	  SELECT FC.COD_SINDICATO',
'	  INTO   VSINDICATO_CATE_PROP',
'    FROM   FILIAIS_CAD FC',
'    WHERE  FC.COD_FILIAL  = NVL(NVL(:P116_FILIAL_VAGA_PROP,:P116_FILIAL_PROP),:P116_FILIAL)',
'    AND    FC.COD_EMPRESA = NVL(NVL(:P116_EMP_VAGA_PROP,:P116_COD_EMPRESA_PROP),:P116_COD_EMPRESA_SOLICITADO);',
'	  --',
'  EXCEPTION',
'  	WHEN OTHERS THEN',
'  	  NULL;',
'  END;',
'  --',
'  IF VSINDICATO_CATE_PROP IS NOT NULL THEN',
'  :p116_SINDICATO_CATE_PROP := VSINDICATO_CATE_PROP;',
'  :P116_SIND_PONTO_DE_FX_NVL := VSINDICATO_CATE_PROP;',
'  END IF;',
'  --',
'END;',
''))
,p_attribute_02=>'P116_FILIAL_VAGA_PROP,P116_FILIAL_PROP,P116_FILIAL,P116_EMP_VAGA_PROP,P116_COD_EMPRESA_PROP,P116_COD_EMPRESA_SOLICITADO'
