,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    CURSOR C1 IS',
'        SELECT DISTINCT b.COD_CAT_GRUPOS_SALARIAIS codigo, ',
'               b.descricao descricao,',
'               a.cod_sindicato,',
'               a.rt_jornada_mensal',
'        FROM  grupos_ponto_faixa_aux a, categoria_grupos_salariais b ',
'        WHERE a.cod_cat_grupos_salariais = b.cod_cat_grupos_salariais',
'        AND   a.cod_grupos_salariais     = nvl(:P116_GRUPO_SALARIAL_PROP_1,:P116_GRUPO_SALARIAL_PROP)',
'        AND   a.cod_empresa_sindjorn     = nvl(:P116_COD_EMPRESA_PROP, :P116_COD_EMPRESA_SOLICITADO)',
'        and   a.cod_sindicato            = nvl(:P116_SINDICATO_CATE_PROP,:P116_NUM_SIND_DISS) -- or a.cod_sindicato = 999) (Adriana)',
'        ORDER BY 1;',
'',
'V_C1 C1%ROWTYPE;',
'',
'BEGIN',
'    ',
'OPEN  C1;',
'FETCH C1 INTO V_C1;',
'CLOSE C1;    ',
'',
'',
'IF V_C1.CODIGO IS NOT NULL THEN',
'',
'    :P116_SIND_PONTO_DE_FX_PROP := V_C1.COD_SINDICATO;',
'    -- :p116_DESC_GRADE                 := V_C1.DESCRICAO;',
'    :P116_JORN_PONTO_DE_FX_PROP   := V_C1.RT_JORNADA_MENSAL;',
'',
'ELSE',
'  :p116_SIND_PONTO_DE_FX_PROP := 999;',
'    :p116_JORN_PONTO_DE_FX_PROP   := ''NUL'';',
'END IF;    ',
'',
'END;'))
,p_attribute_02=>'P116_GRUPO_SALARIAL_PROP_1,P116_GRUPO_SALARIAL_PROP,P116_COD_EMPRESA_PROP,P116_COD_EMPRESA_SOLICITADO,P116_SINDICATO_CATE_PROP,P116_NUM_SIND_DISS'
,p_attribute_03=>'P116_SIND_PONTO_DE_FX_PROP,P116_JORN_PONTO_DE_FX_PROP'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
