,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'v_item_validacao varchar2(100) := :P116_ITEM_VALIDACAO;',
'',
'begin',
' ',
' :p116_mensagem := null;',
'',
'    pkg_alt_func.Valida_Ponto_De_Faixa_Prop(nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'                                           ,:P116_grupo_salarial_prop',
'                                           ,:P116_cod_cat_grupos_sal_prop',
'                                           ,:P116_sindicato_ponto_de_fx',
'                                           ,:P116_sind_ponto_de_fx_prop',
'                                           ,:P116_pto_med',
'                                           ,:P116_pto_min',
'                                           ,:P116_cargo_prop',
'                                           ,:P116_cargo',
'                                           ,:P116_dt_salario_prop',
'                                           ,:P116_ponto_de_faixa_prop',
'                                           ,v_flg_retorno',
'                                           ,v_msg_retorno);',
'                                    ',
' if trim(v_msg_retorno) is not null then',
'    :P116_ITEM_VALIDACAO := TRIM(UPPER(''P116_ponto_de_faixa_prop''));',
'    :p116_ok       := ''N'';',
'    :p116_flag     := v_flg_retorno;',
'    :p116_mensagem := v_msg_retorno;',
' else',
'    :p116_flag     := null;',
'    :p116_mensagem := null;',
'    if v_item_validacao = TRIM(UPPER(''P116_ponto_de_faixa_prop'')) OR v_item_validacao IS NULL then',
'       :P116_OK := ''S'';',
'       :P116_ITEM_VALIDACAO := null;',
'    else',
'       :P116_ITEM_VALIDACAO := v_item_validacao;',
'    end if;',
' end if;',
' ',
'end;',
'',
'',
'declare',
'',
'cursor c1 is',
'select a.cod_empresa,',
'a.cod_filial,',
'a.cod_ccusto,',
'a.cod_cargo,',
'a.cod_funcao,',
'a.cod_ccusto_contab,',
'a.cod_un_negocio,',
'a.cod_unidade_adm,',
'a.cod_local_trab,',
'a.remuneracao',
'  from cl_vaga                a',
' where a.cod_vaga = :p116_cad_vaga_prop',
'   and a.cod_empresa = :p116_emp_vaga_prop',
'   and a.cod_filial = :p116_filial_vaga_prop;',
' ',
'v_c1 c1%rowtype;',
'',
'cursor c2 is',
'select a.cod_empresa,',
'a.filial cod_filial,',
'a.cod_ccusto,',
'a.cargo cod_cargo,',
'a.funcao cod_funcao,',
'c.cod_ccusto_cont cod_ccusto_contab,',
'u.cod_un_negocio,',
'a.unidade_adm cod_unidade_adm,',
'a.cod_localizacao cod_local_trab,',
'a.salario',
'  from informacoes_funcionais_cad a, centro_de_custo c, unidade_de_negocio u',
' where a.cod_empresa = c.cod_empresa',
'   and a.cod_empresa = nvl(u.cod_empresa, a.cod_empresa) ',
'   and a.cod_ccusto = c.cod',
'   and c.cod_ccusto_cont = u.cod_ccusto_contab (+)',
'   and a.cod_empresa = :p116_cod_empresa_solicitado',
'   and a.matricula = :p116_mat_solicitado;',
'   ',
'v_c2 c2%rowtype;',
'',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
' ',
' open c2;',
' fetch c2 into v_c2;',
' close c2;',
' ',
' if v_c1.cod_empresa <> v_c2.cod_empresa then',
'   :p116_dt_empresa_prop := :p116_dt_vigencia;',
' else ',
'   :p116_dt_empresa_prop := null;',
' end if;',
' ',
' if v_c1.cod_filial <> v_c2.cod_filial then',
'   :p116_dt_filial_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_filial_prop := null;',
' end if;',
' ',
' if v_c1.cod_ccusto <> v_c2.cod_ccusto then',
'   :p116_dt_ccusto_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_ccusto_prop := null;',
' end if;',
' ',
' if v_c1.cod_cargo <> v_c2.cod_cargo then',
'   :p116_dt_cargo_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_cargo_prop := null;',
' end if;',
' ',
' if v_c1.cod_funcao <> v_c2.cod_funcao then',
'   :p116_dt_funcao_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_funcao_prop := null;',
' end if;',
' ',
' if v_c1.cod_ccusto_contab <> v_c2.cod_ccusto_contab then',
'   :p116_dt_ccusto_contab := :p116_dt_vigencia;',
' else',
'   :p116_dt_ccusto_contab := null;',
' end if;',
' ',
' if v_c1.cod_unidade_adm <> v_c2.cod_unidade_adm then',
'   :p116_dt_unid_adm_prop := :p116_dt_vigencia;',
' else',
'   :p116_dt_unid_adm_prop := null;',
' end if;',
'',
' if v_c1.cod_local_trab <> v_c2.cod_local_trab then',
'   :P116_DT_LOCAL_PROP := :p116_dt_vigencia;',
' else',
'   :P116_DT_LOCAL_PROP  := null;',
' end if;',
' ',
' if nvl(v_c1.remuneracao,0) <> nvl(v_c2.salario,0) then',
'   :P116_DT_SALARIO_PROP := :p116_dt_vigencia;',
' else',
'   :P116_DT_SALARIO_PROP  := null;',
' end if;',
'',
'end;'))
,p_attribute_02=>'P116_COD_EMPRESA_SOLICITADO,P116_GRUPO_SALARIAL_PROP,P116_COD_CAT_GRUPOS_SAL_PROP,P116_SINDICATO_PONTO_DE_FX,P116_SIND_PONTO_DE_FX_PROP,P116_CARGO_PROP,P116_CARGO,P116_DT_SALARIO_PROP,P116_PONTO_DE_FAIXA_PROP,P116_COD_EMPRESA_PROP,P116_ITEM_VALIDACAO'
