wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(786027699657276498)
,p_event_id=>wwv_flow_api.id(786026759891276498)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'Select R.cod',
'from REG_TRABALHO R',
'WHERE R.COD = :P116_REG_TRAB ',
' AND R.COD_EMPRESA = :P116_COD_EMPRESA_SOLICITADO',
' and not exists (select 1 ',
'                   from sind_reg_trabalho x ',
'                  where x.cod_empresa = r.cod_empresa ',
'                    and x.cod_sindicato = :P116_NOVO_SINDICATO',
'                   -- and x.cod_reg_trab = r.cod',
'                )',
' union',
' Select R.cod',
'from REG_TRABALHO R, SIND_REG_TRABALHO S',
'WHERE R.COD <> ''NULL''',
' AND R.COD = S.COD_REG_TRAB',
' AND R.COD_EMPRESA = S.COD_EMPRESA',
' AND R.COD_EMPRESA = :P116_COD_EMPRESA_SOLICITADO',
' AND S.COD_SINDICATO = :P116_NOVO_SINDICATO',
' AND R.COD = :P116_REG_TRAB;',
' ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
'if v_c1.cod is null and NVL(:P116_BLK_JORNADA,''N'') <> ''S'' and NVL(:P116_BLK_HORARIO,''N'') <> ''S'' then',
'   :P116_BLK_JORNADA := ''S'';',
'   :P116_BLK_HORARIO := ''S'';',
'   :p116_flag := ''N'';',
unistr('   :p116_mensagem := ''Informe uma Nova Jornada de Trabalho e um Novo Hor\00E1rio!'';'),
'end if;',
'',
'exception when others then',
'Null;',
'end;'))
,p_attribute_02=>'P116_REG_TRAB,P116_COD_EMPRESA_SOLICITADO,P116_NOVO_SINDICATO'
,p_attribute_03=>'P116_FLAG,P116_MENSAGEM'
,p_attribute_04=>'Y'
,p_wait_for_result=>'Y'
);
