,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'    cursor c1 is',
'    SELECT ID_BLOQUEIO_SALARIO bloqueia ',
'    FROM USUARIO_ORACLE ',
'    WHERE NM_USUARIO_ORACLE = :P_USUARIO; ',
'',
'    v_c1 c1%rowtype;',
'',
'begin',
'',
'  open c1; ',
'  fetch c1 into v_c1; ',
'  close c1;',
'',
'--    :p116_blk_vaga := ''S'';',
'    :p116_blk_empresa := ''S'';',
'    :p116_blk_filial := ''S'';',
'    :p116_blk_hierarquia := ''S'';',
'    :p116_blk_ccusto_cont := ''S'';',
'    :p116_blk_unid_adm := ''S'';',
'    --:p116_blk_departamento := ''S'';',
'    :p116_blk_emprestimo := ''S'';',
'    :p116_blk_cargo := ''S'';',
'    :p116_blk_local := ''S'';',
'',
'        if nvl(v_c1.bloqueia,''N'') = ''S'' then ',
'          :P116_BLK_SALARIO := ''N'';',
'        elsif f_acesso_salario_apex(:p116_cod_empresa_solicitado, :p116_mat_solicitado, :p116_filial, :p_usuario) = ''N'' then ',
'          :P116_BLK_SALARIO := ''N'';',
'        else ',
'          :P116_BLK_SALARIO := ''S'';',
'        end if;',
'',
'    if :P116_PERMITE_MP_SITUACAO = ''S'' then',
'       :p116_blk_situacao := ''S'';',
'    end if;',
'',
'    :p116_blk_jornada := ''S'';',
'    :p116_blk_horario := ''S'';',
'    :p116_blk_atividade := ''S'';',
'    :p116_blk_sindicato := ''S'';',
'    :p116_blk_valor_faturavel := ''S'';',
'    :p116_blk_tipo_modalidade := ''S'';',
'',
'end;'))
,p_attribute_02=>'P116_PERMITE_MP_SITUACAO,P_USUARIO,P116_COD_EMPRESA_SOLICITADO,P116_MAT_SOLICITADO,P116_FILIAL'
,p_attribute_03=>'P116_BLK_VAGA,P116_BLK_EMPRESA,P116_BLK_FILIAL,P116_BLK_HIERARQUIA,P116_BLK_CCUSTO_CONT,P116_BLK_UNID_ADM,P116_BLK_VALOR_FATURAVEL,P116_BLK_EMPRESTIMO,P116_BLK_CARGO,P116_BLK_LOCAL,P116_BLK_SALARIO,P116_BLK_SITUACAO,P116_BLK_JORNADA,P116_BLK_HORARIO,'
