unistr(' v_msg_retorno := ''2 - A somat\00F3ria do sal\00E1rio com a remunera\00E7\00E3o vari\00E1vel n\00E3o pode ser maior que o total da remunera\00E7\00E3o.'';'),
'end if;',
'    ',
' if trim(v_msg_retorno) is not null then',
'    :P116_ITEM_VALIDACAO := TRIM(UPPER(''p116_remuneracao_variavel_3''));',
'    :p116_ok       := ''N'';',
'    :p116_flag     := v_flg_retorno;',
'    :p116_mensagem := v_msg_retorno;',
' else',
'    :p116_flag     := null;',
'    :p116_mensagem := null;',
'    if v_item_validacao = TRIM(UPPER(''p116_remuneracao_variavel_3'')) OR v_item_validacao IS NULL then',
'       :P116_OK := ''S'';',
'       :P116_ITEM_VALIDACAO := null;',
'    else',
'       :P116_ITEM_VALIDACAO := v_item_validacao;',
'    end if;',
' end if;',
' ',
'end;'))
,p_attribute_02=>'P116_ITEM_VALIDACAO,P116_SALARIO_PROP,P116_REMUNERACAO_VARIAVEL_PROP,P116_TOTAL_REMUNERACAO_PROP'
,p_attribute_03=>'P116_ITEM_VALIDACAO,P116_OK,P116_FLAG,P116_MENSAGEM'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
