,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('declare -- Popula Sal\00E1rio Proposto'),
'',
'v_perc  number(14,2);',
'v_total number(14,2);',
'v_sal_calc number(14,2) := :p116_salario_prop;',
'',
'begin',
'/*',
'v_perc := (nvl(:p116_perc_salario,0)/100)+1;',
'',
'v_total := round(nvl(:p116_salario,0) * v_perc,2);',
'',
':p116_salario_prop := nvl(v_total,0);',
'*/',
'  if :p116_perc_salario > 0 and ((:p116_cad_vaga_prop is not null and nvl(:p116_flg_utiliza_sal_posicao,''N'') = ''N'') or :p116_cad_vaga_prop is null) then -- headcount set/2021 incluso depois do 1o and',
'   pkg_alt_func.popula_sal_proposto(salario_prop  => v_sal_calc, -- :p116_salario_prop,',
'                                  salario_atual => :p116_salario,',
'                                  perc_prop     => :p116_perc_salario);',
unistr('   -- O arredondamento do percentual est\00E1 alterando indevidamente o sal\00E1rio proposto, caso ele esteja corretamente informado.'),
unistr('  -- O ajuste abaixo \00E9 para evitar essa situa\00E7\00E3o'),
'  if :p116_salario_prop is not null and v_sal_calc is not null and abs(:p116_salario_prop-v_sal_calc) < 0.5 then',
'    :p116_salario_prop := :p116_salario_prop;',
'  else',
'    :p116_salario_prop := v_sal_calc;',
'  end if;',
' else',
'   if :p116_cad_vaga_prop is null then -- headcount set/2021',
'     :p116_salario_prop := null;',
'   end if;',
' end if;',
'',
'end;'))
,p_attribute_02=>'P116_PERC_SALARIO,P116_SALARIO,P116_CAD_VAGA_PROP,P116_FLG_UTILIZA_SAL_POSICAO,P116_SALARIO_PROP'
,p_attribute_03=>'P116_SALARIO_PROP'
,p_attribute_04=>'Y'
,p_wait_for_result=>'Y'
);
