,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_tot_rem_prop_new number;',
'',
'begin',
'/*',
'if --:p116_total_remuneracao_prop is null and ',
'   :p116_salario_prop is not null and ',
'   :p116_remuneracao_variavel_prop is null then',
'   ',
'   v_tot_rem_prop_new := :p116_salario_prop + :p116_remuneracao_variavel;',
'',
'   :p116_total_remuneracao_prop := v_tot_rem_prop_new;',
'',
'elsif    :p116_salario_prop is not null and ',
'   :p116_remuneracao_variavel_prop is not null then',
'',
'   v_tot_rem_prop_new := :p116_salario_prop + :p116_remuneracao_variavel_prop;',
'',
'   :p116_total_remuneracao_prop := v_tot_rem_prop_new;',
'',
'end if;',
'*/',
'',
'/*',
'pkg_alt_func.popula_tot_rem_prop (salario_prop => :p116_salario_prop,',
'                               rem_var_prop => :p116_remuneracao_variavel_prop,',
'                               rem_var_atual => :p116_remuneracao_variavel,',
'                               tot_rem_prop => :p116_total_remuneracao_prop);',
'*/                    ',
'                               ',
'pkg_alt_func.popula_tot_rem_prop (salario_atual => :p116_salario,',
'                                  salario_prop  => :p116_salario_prop,',
'                                  rem_var_atual => :p116_remuneracao_variavel,',
'                                  rem_var_prop => :p116_remuneracao_variavel_prop,',
'                                  vlr_aux_atual => :p116_vlr_aux_tipo_modalidade,',
'                                  vlr_aux_prop => :p116_vlr_aux_tipo_mod_prop,',
'                                  tot_rem_prop => :p116_total_remuneracao_prop);',
'                /*                  ',
'IF :P116_VLR_AUX_TIPO_MODALIDADE_HIDDEN IS NOT NULL THEN',
' :P116_TOTAL_REMUNERACAO_PROP := :P116_TOTAL_REMUNERACAO_PROP + :P116_VLR_AUX_TIPO_MODALIDADE_HIDDEN;',
'END IF;           */                    ',
'',
'end;'))
,p_attribute_02=>'P116_TOTAL_REMUNERACAO_PROP,P116_SALARIO_PROP,P116_REMUNERACAO_VARIAVEL_PROP,P116_REMUNERACAO_VARIAVEL,P116_SALARIO,P116_VLR_AUX_TIPO_MODALIDADE,P116_VLR_AUX_TIPO_MOD_PROP,P116_VLR_AUX_TIPO_MODALIDADE_HIDDEN'
