,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'v_item_validacao varchar2(100) := :P116_ITEM_VALIDACAO;',
'begin',
'',
' :p116_mensagem := null;',
'',
'if nvl(:P116_SALARIO_PROP,0) > 0 or nvl(:P116_REMUNERACAO_VARIAVEL_PROP,0) > 0 then',
'',
'  if (nvl(:P116_SALARIO,0) + ',
'      nvl(:P116_REMUNERACAO_VARIAVEL,0))',
'      >',
'  (nvl(:P116_SALARIO_PROP,0) + ',
'      nvl(:P116_REMUNERACAO_VARIAVEL_PROP,0))',
unistr('  --:p116_total_remuneracao > :p116_total_remuneracao_prop /*Comentado pois o total n\00E3o deve considerar o valor do aux\00EDlio, pois este pode diminuir*/'),
'  then',
'       v_flg_retorno := ''N'';',
unistr('       v_msg_retorno := ''O Total de Remunera\00E7\00E3o Proposta n\00E3o pode ser menor que o Atual.'';'),
'  end if;            ',
'',
'end if;',
'',
' if trim(v_msg_retorno) is not null then',
'    :P116_ITEM_VALIDACAO := TRIM(UPPER(''p116_total_salario_prop''));',
'    :p116_ok       := ''N'';',
'    :p116_flag     := v_flg_retorno;',
'    :p116_mensagem := v_msg_retorno;',
' else',
'    :p116_flag     := null;',
'    :p116_mensagem := null;',
'    if v_item_validacao = TRIM(UPPER(''p116_total_salario_prop'')) OR v_item_validacao IS NULL then',
'       :P116_OK := ''S'';',
'       :P116_ITEM_VALIDACAO := null;',
'    else',
'       :P116_ITEM_VALIDACAO := v_item_validacao;',
'    end if;',
' end if;',
' ',
'end;'))
,p_attribute_02=>'P116_ITEM_VALIDACAO,P116_TOTAL_REMUNERACAO,P116_TOTAL_REMUNERACAO_PROP,P116_SALARIO,P116_SALARIO_PROP,P116_REMUNERACAO_VARIAVEL,P116_REMUNERACAO_VARIAVEL_PROP'
,p_attribute_03=>'P116_ITEM_VALIDACAO,P116_MENSAGEM,P116_OK,P116_FLAG'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
end;
