'',
' :p116_flag     := null;',
' :p116_mensagem := null;',
'',
'pkg_req_beneficio.valida_saldo(:p116_saldo, NULL, v_flg_retorno, v_msg_retorno);',
'',
' if trim(v_msg_retorno) is not null then',
'    :P116_ITEM_VALIDACAO := TRIM(UPPER(''VALIDA_SALDO 1''));',
'    :P116_ok       := ''N'';',
'    :P116_flag     := v_flg_retorno;',
'    :P116_mensagem := v_msg_retorno;',
' else',
'    :P116_flag     := null;',
'    :P116_mensagem := null;',
'    if v_item_validacao = TRIM(UPPER(''VALIDA_SALDO 1'')) OR v_item_validacao IS NULL then',
'       :P116_OK := ''S'';',
'       :P116_ITEM_VALIDACAO := null;',
'    else',
'       :P116_ITEM_VALIDACAO := v_item_validacao;',
'       :P116_OK := ''N'';',
'    end if;',
' end if;',
' ',
'end;'))
,p_attribute_02=>'P116_ITEM_VALIDACAO,P116_SALDO'
,p_attribute_03=>'P116_ITEM_VALIDACAO,P116_OK,P116_FLAG,P116_MENSAGEM'
