begin
wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(786257344996276545)
,p_event_id=>wwv_flow_api.id(786256852573276545)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'pkg_req_beneficio.Popula_Valor (nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado),',
'                        :p116_mat_solicitado,',
'                        :p116_beneficio,',
'                        :p116_tipo_beneficio,',
'                        :p116_valor_min,',
'                        :p116_valor_max,',
'                        :p116_valor,',
'                        :p116_quantidade,',
'                        nvl(:P116_SALARIO_PROP,:P116_SALARIO),',
