,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'  v_flg varchar2(3);',
'  v_msg varchar2(4000);',
'',
'  v_remuneracao_variavel NUMBER := replace(replace(nvl(:P116_REMUNERACAO_VARIAVEL_PROP,:P116_REMUNERACAO_VARIAVEL),''R$''),''.'');',
'',
'  v_valor_beneficio number;',
'',
'  cursor c1 is',
'  select *',
'    from TMP_VALIDA_ELEG_BENEFICIO i',
'   where i.seq = :p116_seq_beneficio;',
'   ',
'  v_c1 c1%rowtype;',
'  ',
'  CURSOR C2 IS',
'  select ''S'' existe--v.cod_familia, v.tipo_cod_familia',
'  from beneficios_familia b, beneficios_familia_tipo t, beneficios_fam_tipo_vlr v, TMP_VALIDA_ELEG_BENEFICIO i, cargos c, centro_de_custo cc',
' where b.cod_empresa = t.cod_empresa',
'   and b.cod_empresa = v.cod_empresa',
'   and b.cod_empresa = i.empresa',
'   and b.cod_empresa = cc.cod_empresa',
'   and b.cod_familia = t.cod_familia',
'   and b.cod_familia = v.cod_familia',
'   and t.tipo_cod_familia = v.tipo_cod_familia',
'   and i.cargo = c.cod',
'   and i.ccusto = cc.cod',
'   and sysdate between b.dt_inicio_familia and nvl(b.dt_fim_familia,sysdate)',
'   and sysdate between t.dt_inicio_tipo and nvl(t.dt_fim_tipo,sysdate)',
'   and sysdate between v.dt_inicio_valor and nvl(v.dt_fim_valor,sysdate)',
'   and b.req_colab = ''S''',
'   and t.req_colab = ''S''',
'   and i.seq = :p116_seq_beneficio',
'   and fnct_valida_eleg_beneficio(i.empresa, ',
'i.matricula, ',
'i.vaga, ',
'b.cod_familia, ',
't.tipo_cod_familia,',
'trunc(sysdate),',
'i.filial,',
'c.class_cargo,',
'i.grupo_sal,',
'i.sindicato,',
'i.ccusto,',
'i.unid_adm,',
'i.unid_neg, ',
'i.atividade,',
'null,',
'i.perc_ben_var,',
'i.cargo,',
'i.rt_jornada_mensal,',
'i.vinculo,',
'i.seq,',
'i.cod_horario) = ''S''',
'   and b.cod_familia <> ''BC''',
'   and exists (select 1 ',
'from incor_beneficios_funcionais x',
'where x.cod_empresa = :p116_cod_empresa_solicitado',
'and x.matricula = :p116_mat_solicitado',
'and x.flag = v.cod_familia',
'and x.tipo = v.tipo_cod_familia',
'and trunc(sysdate) between nvl(dt_inicio,trunc(sysdate)) and nvl(dt_fim,trunc(sysdate)));',
'                ',
'  v_c2 c2%rowtype;',
'',
'begin',
'',
'  if NVL(v_remuneracao_variavel,0) > 0 then',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
'  pkg_pessoal.retorna_benef_sindicato (v_c1.empresa,',
'     v_c1.filial,',
'     v_c1.ccusto,',
'     v_c1.cargo,',
'     v_c1.sindicato,',
'     v_c1.unid_adm,',
'     v_c1.unid_neg,',
'     v_c1.atividade,',
'     v_c1.vaga,',
'     ''N'',--:p116_refeitorio,',
'     v_c1.vinculo,',
'     v_valor_beneficio,',
'     null,',
'     v_c1.RT_JORNADA_MENSAL,',
'     v_c1.cod_horario);',
'',
'    if v_remuneracao_variavel <> v_valor_beneficio AND nvl(v_valor_beneficio,0) > 0 and nvl(:P116_REQ_BENEFICIOS,''N'') = ''N'' then',
'       if nvl(v_valor_beneficio,0) > nvl(v_remuneracao_variavel,0) then',
'           if instr(1/2,''.'') > 0 then',
'              EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= '''',.'''' '';',
'           end if;',
'       :P116_REMUNERACAO_VARIAVEL_PROP := nvl(v_valor_beneficio,0);',
'       :P116_PERC_REMUNERACAO_VAR_PROP := /*floor*/round(((nvl(v_valor_beneficio,0) / nvl(:p116_remuneracao_variavel,0))-1)* 100,4);',
'       end if;',
'    else',
'    ',
'        open c2;',
'        fetch c2 into v_c2;',
'        close c2;',
'        ',
'        if nvl(v_c2.existe,''N'') = ''S'' then',
'          null;',
'        else',
'           if nvl(v_valor_beneficio,0) > nvl(v_remuneracao_variavel,0) then',
'               if instr(1/2,''.'') > 0 then',
'                  EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= '''',.'''' '';',
'               end if;',
'       :P116_REMUNERACAO_VARIAVEL_PROP := nvl(v_valor_beneficio,0);',
'       :P116_PERC_REMUNERACAO_VAR_PROP := /*floor*/round(((nvl(v_valor_beneficio,0) / nvl(:p116_remuneracao_variavel,0))-1)* 100,4);',
'           end if;',
'        end if;',
'',
'    end if;',
'',
'  end if;',
'  ',
'end;'))
,p_attribute_02=>'P116_REMUNERACAO_VARIAVEL_PROP,P116_REMUNERACAO_VARIAVEL,P116_SEQ_BENEFICIO,P116_REQ_BENEFICIOS,P116_COD_EMPRESA_SOLICITADO,P116_MAT_SOLICITADO'
