,p_event_id=>wwv_flow_api.id(786285524980276552)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select sum(nvl(b.valor,0) * nvl(b.quantidade,1)) soma',
'  from REQ_BENEFICIOS_ITENS_TEMP B, beneficios_fam_tipo_vlr v',
' where b.cod_empresa = v.cod_empresa',
'   and b.cod_familia = v.cod_familia',
'   and b.tipo_cod_familia = v.tipo_cod_familia',
'   and v.desconta_saldo = ''S''',
'   and b.cod_empresa = :P116_COD_EMPRESA_SOLICITADO',
'   and b.matricula = :p116_mat_solicitado',
'   and nvl(b.operacao,''Z'') <> ''D'';',
'   ',
'v_c1 c1%rowtype;',
'  ',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
':p116_saldo := :p116_total - nvl(v_c1.soma,0);',
'',
'end;'))
,p_attribute_02=>'P116_COD_EMPRESA_SOLICITADO,P116_MAT_SOLICITADO,P116_TOTAL'
,p_attribute_03=>'P116_SALDO'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
