,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'v_item_validacao varchar2(100) := :P116_ITEM_VALIDACAO;',
'begin',
'',
'--',
'',
' :p116_mensagem := null;',
'',
'    pkg_alt_func.Valida_Perc_Remun (nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'                              ,:P116_MAT_SOLICITADO',
'                              ,:P116_MOT_ALT_SAL_PROP',
'                              ,:p116_perc_salario',
'                              ,v_flg_retorno',
'                              ,v_msg_retorno);                                                    ',
'                                    ',
' if trim(v_msg_retorno) is not null then',
'    if v_flg_retorno = ''N'' then',
'    :P116_ITEM_VALIDACAO := TRIM(UPPER(''p116_perc_salario''));',
'    :p116_ok       := ''N'';',
'    :p116_flag     := v_flg_retorno;',
'    :p116_mensagem := v_msg_retorno;',
'    else',
'    :p116_ok       := ''S'';',
'    :p116_flag     := v_flg_retorno;',
'    :p116_mensagem := v_msg_retorno;',
'    end if;',
' else',
'    :p116_flag     := null;',
'    :p116_mensagem := null;',
'    if v_item_validacao = TRIM(UPPER(''p116_perc_salario'')) OR v_item_validacao IS NULL then',
'       :P116_OK := ''S'';',
'       :P116_ITEM_VALIDACAO := null;',
'    else',
'       :P116_ITEM_VALIDACAO := v_item_validacao;',
'    end if;',
' end if;',
' ',
'end;'))
,p_attribute_02=>'P116_COD_EMPRESA_PROP,P116_COD_EMPRESA_SOLICITADO,P116_SALARIO_PROP,P116_MOT_ALT_SAL_PROP,P116_PERC_SALARIO,P116_ITEM_VALIDACAO,P116_MAT_SOLICITADO'
,p_attribute_03=>'P116_OK,P116_FLAG,P116_MENSAGEM,P116_ITEM_VALIDACAO'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
end;
