 p_id=>wwv_flow_api.id(786082184946276509)
,p_event_id=>wwv_flow_api.id(786081733693276509)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'CURSOR C1 IS',
'SELECT NVL(DIA_LIMITE_BENEFICIOS,1) DIA_LIMITE_BENEFICIOS, nvl(req_benef_mes_seguinte,''S'') req_benef_mes_seguinte',
'  FROM PARAMETROS_RECURSOS_HUMANOS',
' WHERE COD_EMPRESA = :p116_cod_empresa_solicitado;',
' ',
'V_C1 C1%ROWTYPE;',
'',
'cursor c2 is',
'SELECT DISTINCT dt_vigencia_ini',
'  FROM req_beneficios_itens',
' WHERE cod_req_alt_func = :p116_cod_solicitacao',
'   AND nvl(operacao,''X'') = ''I'';',
'',
'v_c2 c2%rowtype;',
'',
'v_data date;',
'',
'v_dt date := nvl(:P116_DT_VIGENCIA_BENEF,SYSDATE);',
'v_dt_vlr_aux date := nvl(:P116_DT_VLR_AUX_TIPO_MOD_PROP,SYSDATE);',
'',
'begin',
'',
'OPEN C1;',
'FETCH C1 INTO V_C1;',
'CLOSE C1;',
'',
'if :p116_rowid is not null then',
'',
' v_data := :P116_DT_VIGENCIA_BENEF;',
' ',
'    OPEN C2;',
'    FETCH C2 INTO V_C2;',
'    CLOSE C2;',
'',
'end if;',
'',
'if v_c2.dt_vigencia_ini is not null and ',
'   :P116_DT_VIGENCIA_BENEF is null and ',
'   :p116_rowid is not null then',
'',
'   v_data := v_c2.dt_vigencia_ini;',
'',
'   :P116_DT_VIGENCIA_BENEF := v_data;',
'',
'elsif v_c2.dt_vigencia_ini is null and ',
'   :P116_DT_VIGENCIA_BENEF is null and ',
'   :p116_rowid is not null then',
'/*',
'   IF to_number(to_char(TRUNC(v_dt),''DD'')) > V_C1.DIA_LIMITE_BENEFICIOS THEN',
'    V_DATA := TO_DATE(TO_CHAR(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),2),''MON-RRRR'')));',
'   ELSE',
'    V_DATA := TO_DATE(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),1),''MON-RRRR''));',
'   END IF;',
'*/',
'  IF to_number(to_char(TRUNC(v_dt),''DD'')) > V_C1.DIA_LIMITE_BENEFICIOS THEN',
'    IF V_C1.REQ_BENEF_MES_SEGUINTE = ''S'' THEN',
'      V_DATA := TO_DATE(TO_CHAR(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),2),''MON-RRRR'')));',
'    ELSE',
'      V_DATA := TO_DATE(TO_CHAR(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),1),''MON-RRRR'')));',
'    END IF;',
'  ELSE',
'    IF V_C1.REQ_BENEF_MES_SEGUINTE = ''S'' THEN',
'      V_DATA := TO_DATE(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),1),''MON-RRRR''));',
'    ELSE',
'      V_DATA := TO_DATE(''01-''||TO_CHAR(TRUNC(v_dt),''MON-RRRR''));',
'    END IF;',
'  END IF;',
'',
'   :P116_DT_VIGENCIA_BENEF := V_DATA;',
'',
'elsif v_c2.dt_vigencia_ini is not null and ',
'   :P116_DT_VIGENCIA_BENEF is not null and',
'   v_c2.dt_vigencia_ini <> :P116_DT_VIGENCIA_BENEF and',
'   :p116_rowid is not null then ',
'',
'   v_data := :P116_DT_VIGENCIA_BENEF;',
'',
'elsif :p116_rowid is null then',
'',
'  IF :P116_TIPO_MODALIDADE_PROP is null then',
'/*',
'   IF to_number(to_char(TRUNC(v_dt),''DD'')) > V_C1.DIA_LIMITE_BENEFICIOS THEN',
'    V_DATA := TO_DATE(TO_CHAR(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),2),''MON-RRRR'')));',
'   ELSE',
'    V_DATA := TO_DATE(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),1),''MON-RRRR''));',
'   END IF;',
'*/',
'  IF to_number(to_char(TRUNC(v_dt),''DD'')) > V_C1.DIA_LIMITE_BENEFICIOS THEN',
'    IF V_C1.REQ_BENEF_MES_SEGUINTE = ''S'' THEN',
'      V_DATA := TO_DATE(TO_CHAR(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),2),''MON-RRRR'')));',
'    ELSE',
'      V_DATA := TO_DATE(TO_CHAR(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),1),''MON-RRRR'')));',
'    END IF;',
'  ELSE',
'    IF V_C1.REQ_BENEF_MES_SEGUINTE = ''S'' THEN',
'      V_DATA := TO_DATE(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt),1),''MON-RRRR''));',
'    ELSE',
'      V_DATA := TO_DATE(''01-''||TO_CHAR(TRUNC(v_dt),''MON-RRRR''));',
'    END IF;',
'  END IF;',
'',
'   :P116_DT_VIGENCIA_BENEF := V_DATA;',
'  end if;',
'  ',
'  IF :P116_TIPO_MODALIDADE_PROP = ''P'' and :P116_TIPO_MODALIDADE <> ''P'' then',
'   IF to_number(to_char(TRUNC(v_dt_vlr_aux),''DD'')) > V_C1.DIA_LIMITE_BENEFICIOS THEN',
'    V_DATA := TO_DATE(TO_CHAR(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt_vlr_aux),1),''MON-RRRR'')));',
'   ELSE',
'    V_DATA := v_dt_vlr_aux; --TO_DATE(''01-''||TO_CHAR(ADD_MONTHS(TRUNC(v_dt_vlr_aux),1),''MON-RRRR''));',
'   END IF;',
'',
'   :P116_DT_VIGENCIA_BENEF := V_DATA;',
'  end if;',
'',
'end if;',
'',
unistr('    :P116_TEXTO_DIA_LIMITE := ''O pedido de benef\00EDcios ser\00E1 validado para o dia ''||V_DATA||'', com recebimento no m\00EAs subsequente.'';'),
'end;'))
,p_attribute_02=>'P116_COD_EMPRESA_SOLICITADO,P116_COD_SOLICITACAO,P116_ROWID,P116_DT_VIG_SALARIO_PROP,P116_DT_VIGENCIA_BENEF,P116_TIPO_MODALIDADE_PROP,P116_TIPO_MODALIDADE,P116_DT_VLR_AUX_TIPO_MOD_PROP'
,p_attribute_03=>'P116_DT_VIGENCIA_BENEF,P116_TEXTO_DIA_LIMITE'
,p_attribute_04=>'Y'
,p_wait_for_result=>'Y'
);
