wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(786095636823276512)
,p_event_id=>wwv_flow_api.id(786095174083276512)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
' cursor c1 is',
' select cod_empresa||'' - ''||initcap(fnct_nome_empresa(cod_empresa,''S''))||'' / ''||',
'        matricula||'' - ''||initcap(fnct_nome_func(cod_empresa, matricula))||'' / ''||',
'        cargo||'' - ''||initcap(fnct_nome_cargo(cargo)) colaborador',
'   from informacoes_funcionais_cad',
'  where cod_empresa = :p116_COD_EMPRESA_SOLICITANTE',
'    and matricula   = :p116_MAT_SOLICITANTE;',
'',
' v_c1 c1%rowtype;',
'',
'begin',
'',
'if :p116_cod_solicitacao is null and :p116_cod_empresa_solicitante is null and :p116_mat_solicitante is null then',
'    :p116_cod_empresa_solicitante := :P_EMPRESA_USER;',
'    :p116_mat_solicitante := :P_MATRICULA_USER;',
'end if;',
'',
' open c1;',
' fetch c1 into v_c1;',
' close c1;',
'',
' if v_c1.colaborador is not null then',
'    :p116_solicitante := v_c1.colaborador;',
' end if;',
' ',
' BEGIN',
' 		SELECT nvl(FLG_UTILIZA_SALARIO_POSICAO,''N'')',
'		INTO   :p116_FLG_UTILIZA_SAL_POSICAO',
'		FROM   PARAMETROS_RECURSOS_HUMANOS PRH',
'		WHERE  PRH.COD_EMPRESA = NVL(:p116_COD_EMPRESA_prop,:p116_COD_EMPRESA_SOLICITANTE);',
' EXCEPTION',
' WHEN NO_DATA_FOUND THEN ',
' NULL;',
' END;',
' ',
' begin',
'	  SELECT A.UTILIZA_QUADRO_PESSOAL',
'      into :P116_UTILIZA_QUADRO',
'	  FROM   CONFIGURACOES A;',
' end;',
' ',
'end;'))
,p_attribute_02=>'P116_COD_EMPRESA_SOLICITANTE,P116_MAT_SOLICITANTE,P116_COD_SOLICITACAO,P_EMPRESA_USER,P_MATRICULA_USER,P116_COD_EMPRESA_PROP'
,p_attribute_03=>'P116_SOLICITANTE,P116_FLG_UTILIZA_SAL_POSICAO,P116_UTILIZA_QUADRO,P116_COD_EMPRESA_SOLICITANTE,P116_MAT_SOLICITANTE'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
