,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'--',
'    cursor c_sind_cargo (psindicato number, pcargo varchar2, pdt_req date) is',
'    select sind_cod, cargo_cod, valor, dt_inic',
'      from sindicato_cargo_valor',
'     where sind_cod = psindicato',
'       and cargo_cod = pcargo',
'       and pdt_req >= dt_inic;',
'       ',
'    v_sind_cargo c_sind_cargo%rowtype;',
'    --',
'    v_sindicato informacoes_funcionais.num_sind_diss%type;',
'    v_cargo informacoes_funcionais.cargo%type;',
'    v_dt_req date;',
'    VPARC_SALARIO VARCHAR2(1) := :P116_PARC_SALARIO;',
'    --',
'    v_flg_retorno varchar2(1);',
'    v_msg_retorno varchar2(4000);',
'    --',
'  begin',
'    --',
'    if nvl(:p116_salario_prop,0) > 0 then',
'      --',
unistr('      BEGIN -- Ajuste para corrigir a altera\00E7\00E3o indevida da op\00E7\00E3o de SIM e N\00C3O'),
'          IF :P116_ROWID IS NOT NULL THEN',
'            BEGIN',
'              SELECT DISTINCT ''S''',
'              INTO   VPARC_SALARIO',
'              FROM   SOLIC_APROV_PARC_SALARIO',
'              WHERE  COD_SOLICITACAO = :P116_COD_SOLICITACAO;',
'            EXCEPTION',
'              WHEN OTHERS THEN',
'                NULL;',
'            END;',
'          END IF;',
'          :P116_PARC_SALARIO :=  VPARC_SALARIO;',
'      END;',
'      --',
'      v_sindicato := nvl(:p116_novo_sindicato,:p116_num_sind_diss);',
'      v_cargo := nvl(:p116_cargo_prop,:p116_cargo);',
'      v_dt_req := :P116_DT_SALARIO_PROP;',
'      --',
'      open c_sind_cargo(v_sindicato, v_cargo, v_dt_req);',
'      fetch c_sind_cargo into v_sind_cargo;',
'      close c_sind_cargo;',
'      ',
'     if v_sind_cargo.sind_cod is not null then',
'        if nvl(v_sind_cargo.valor,0) = nvl(:p116_salario_prop,0) then',
'--          :p116_parc_salario := ''N'';',
'--          :P116_N_PARCELAMENTO_SAL := ''N'';',
'null;',
'        end if;',
'/*      else',
unistr('        BEGIN -- Ajuste para corrigir a altera\00E7\00E3o indevida da op\00E7\00E3o de SIM e N\00C3O'),
'          IF :P116_ROWID IS NOT NULL THEN',
'            BEGIN',
'              SELECT DISTINCT ''S''',
'              INTO   VPARC_SALARIO',
'              FROM   SOLIC_APROV_PARC_SALARIO',
'              WHERE  COD_SOLICITACAO = :P116_COD_SOLICITACAO;',
'            EXCEPTION',
'              WHEN OTHERS THEN',
'                NULL;',
'            END;',
'          END IF;',
'          :P116_PARC_SALARIO :=  VPARC_SALARIO;',
'        END;*/',
'      end if;',
'      --',
'      pkg_alt_func.Valida_Piso_Salario (',
'                           nvl(:p116_salario_prop,0),',
'                           :p116_cod_empresa_nvl,',
'                           :p116_mat_solicitado,',
'                           v_cargo,',
'                           v_sindicato,',
'                           nvl(:P116_REG_TRAB_PROP,:P116_REG_TRAB),',
'                           v_dt_req,',
'                           v_flg_retorno,',
'                           v_msg_retorno);',
'',
'    end if;',
'    --',
'     if trim(v_msg_retorno) is not null and v_flg_retorno = ''N'' then',
'        :p116_ok       := ''N'';',
'        :p116_flag     := v_flg_retorno;',
'        :p116_mensagem := v_msg_retorno;',
'     else',
'        :p116_flag     := v_flg_retorno; -- null;',
'        :p116_mensagem := v_msg_retorno;',
'        :P116_OK := ''S'';',
'     end if;',
'     :P116_PARC_SALARIO := :P116_PARC_SALARIO;',
'    ',
'  end;'))
,p_attribute_02=>'P116_SALARIO_PROP,P116_NOVO_SINDICATO,P116_NUM_SIND_DISS,P116_CARGO_PROP,P116_CARGO,P116_DT_SALARIO_PROP,P116_COD_EMPRESA_NVL,P116_REG_TRAB_PROP,P116_REG_TRAB,P116_MAT_SOLICITADO'
,p_attribute_03=>'P116_PARC_SALARIO,P116_N_PARCELAMENTO_SAL,P116_OK,P116_FLAG,P116_MENSAGEM'
,p_attribute_04=>'N'
,p_wait_for_result=>'Y'
);
