,p_display_when_type=>'FUNCTION_BODY'
,p_display_when_cond=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'SELECT ID_BLOQUEIO_SALARIO bloqueia ',
'FROM USUARIO_ORACLE ',
'WHERE NM_USUARIO_ORACLE = :P_USUARIO; ',
'',
'v_c1 c1%rowtype;',
'',
'begin',
'open c1; ',
'fetch c1 into v_c1; ',
'close c1;',
'',
'    if nvl(v_c1.bloqueia,''N'') = ''S'' then ',
'        return true;',
'    elsif f_acesso_salario_apex(:p116_cod_empresa_solicitado, :p116_mat_solicitado, :p116_filial, :p_usuario) = ''N'' and :p116_rowid is not null then ',
'        return true;',
'    else ',
'        return false;',
'    end if;',
'end;'))
);
