 p_id=>wwv_flow_api.id(786376601039276572)
,p_event_id=>wwv_flow_api.id(786376100913276572)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'  CURSOR C_DADOS IS ',
'    SELECT INF.TIPO_MODALIDADE',
'      ,    INF.MOT_ALT_TIPO_MODALIDADE',
'      ,    INF.DT_TIPO_MODALIDADE',
'      ,    INF.VLR_AUX_TIPO_MODALIDADE',
'      ,    INF.MOT_ALT_VLR_AUX_TP_MODALIDADE',
'      ,    INF.DT_VLR_AUX_TIPO_MODALIDADE',
'     FROM INFORMACOES_FUNCIONAIS_CAD INF',
'    WHERE INF.COD_EMPRESA = :P116_COD_EMPRESA_SOLICITADO ',
'      AND INF.MATRICULA   = :P116_MAT_SOLICITADO;',
'',
'v_dados c_dados%rowtype;',
'',
'BEGIN',
'',
'  OPEN C_DADOS;',
'   FETCH C_DADOS INTO V_DADOS;',
