'	END IF;',
'    ',
'    IF :P116_MOT_ALT_VLR_AUX_TIPO_MOD IS NULL THEN ',
'		:P116_MOT_ALT_VLR_AUX_TIPO_MOD:= V_DADOS.MOT_ALT_VLR_AUX_TP_MODALIDADE;',
'	END IF;',
'    ',
