wwv_flow_api.create_page_da_action(
 p_id=>wwv_flow_api.id(786378449583276572)
,p_event_id=>wwv_flow_api.id(786377920383276572)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('-- Comentado para subir vers\00E3o para produ\00E3o, ainda em testes.'),
'declare ',
' v_total number := 0;',
' ',
' v_flg_retorno varchar2(3);',
' v_msg_retorno varchar2(4000);',
' ',
' begin ',
'  null;',
'/*:p116_mensagem := null;',
' v_msg_retorno := null;',
' ',
'  if :P116_REMUNERACAO_VARIAVEL_PROP is null then ',
'     ',
'     begin',
'       select sum( case when v.desconta_saldo = ''S'' then ',
'                       DECODE(i.operacao,''D'',0,''I'',(nvl(i.quantidade,1)*i.valor),(nvl(i.quantidade,1)*i.valor)) ',
'                      when v.desconta_saldo = ''N'' then null end) Valor_Total ',
'        into v_total             ',
'        from beneficios_familia b, beneficios_familia_tipo t, beneficios_fam_tipo_vlr v, req_beneficios_itens i',
'       where b.cod_empresa = t.cod_empresa',
'         and b.cod_empresa = v.cod_empresa',
'         and b.cod_familia = i.cod_familia',
'         and b.cod_familia = t.cod_familia',
'         and b.cod_familia = v.cod_familia',
'         and t.tipo_cod_familia = v.tipo_cod_familia',
'         and t.tipo_cod_familia = i.tipo_cod_familia',
'         and b.cod_empresa = nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'         and :P116_dt_solicitacao between b.dt_inicio_familia and nvl(b.dt_fim_familia,sysdate)',
'         and :P116_dt_solicitacao between t.dt_inicio_tipo and nvl(t.dt_fim_tipo,sysdate)',
'         and :P116_dt_solicitacao between v.dt_inicio_valor and nvl(v.dt_fim_valor,sysdate)',
'         and i.cod_req_alt_func = :P116_cod_solicitacao;',
'     exception',
'      when others then ',
'       v_total := 0;',
'     end;',
'     ',
'     if v_total > 0 then ',
'      v_flg_retorno := ''N'';',
unistr('      v_msg_retorno := ''Existem beneficios requisitados e o valor n\00E3o pode ser nulo. \00C9 preciso excluir os beneficios requisitados antes de zerar o valor.'';'),
'     end if;',
'     ',
'     if trim(v_msg_retorno) is not null then',
'       :P116_ITEM_VALIDACAO := TRIM(UPPER(''P116_REMUNERACAO_VARIAVEL_PROP''));',
'       :p116_ok       := ''N'';',
'       :p116_flag     := v_flg_retorno;',
'       :p116_mensagem := v_msg_retorno;',
'     end if;',
'    ',
'  end if;',
'*/  ',
' end;',
' '))
,p_attribute_02=>'P116_COD_EMPRESA_PROP,P116_COD_EMPRESA_SOLICITADO,P116_COD_SOLICITACAO,P116_REMUNERACAO_VARIAVEL_PROP'
