,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>unistr('Ajusta Motivo Tranfer\00EAncia entre Filial e Sindicato')
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P116_BLK_FILIAL = ''S'' ',
'    and :P116_BLK_SINDICATO = ''S'' ',
'    and :P116_MOT_ALT_FILIAL_PROP is not null ',
'    and :P116_MOT_ALT_SIND_CATE_PROP is not null then',
'    ',
'    :P116_MOT_ALT_FILIAL_PROP := :P116_MOT_ALT_SIND_CATE_PROP; -- SUBSTR(:P116_MOT_ALT_SIND_CATE_PROP,1,3); --:P116_MOT_ALT_SIND_CATE_PROP; ch44002',
'    ',
'end if;',
'--',
'if :P116_FILIAL_PROP is null and :P116_GUARDA_FILIAL is not null then',
'    :P116_FILIAL_PROP := :P116_GUARDA_FILIAL;',
'end if;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785929734817276472)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Valida Piso Salario - Parcelamento'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'--',
'    cursor c_sind_cargo (psindicato number, pcargo varchar2, pdt_req date) is',
'    select sind_cod, cargo_cod, valor, dt_inic',
'      from sindicato_cargo_valor',
'     where sind_cod = psindicato',
'       and cargo_cod = pcargo',
'       and pdt_req >= dt_inic;',
'       ',
'    v_sind_cargo c_sind_cargo%rowtype;',
'    --',
'    v_sindicato informacoes_funcionais.num_sind_diss%type;',
'    v_cargo informacoes_funcionais.cargo%type;',
'    v_dt_req date;',
'    --',
'  begin',
'    --',
'    if nvl(:p116_salario_prop,0) > 0 then',
'      --',
'      v_sindicato := nvl(:p116_novo_sindicato,:p116_num_sind_diss);',
'      v_cargo := nvl(:p116_cargo_prop,:p116_cargo);',
'      v_dt_req := :P116_DT_SALARIO_PROP;',
'      --',
'      open c_sind_cargo(v_sindicato, v_cargo, v_dt_req);',
'      fetch c_sind_cargo into v_sind_cargo;',
'      close c_sind_cargo;',
'      ',
'      if v_sind_cargo.sind_cod is not null then',
'        if nvl(v_sind_cargo.valor,0) = nvl(:p116_salario_prop,0) then',
'          :p116_parc_salario := ''N'';',
'        end if;',
'      end if;',
'      --',
'    end if;',
'    --',
'  end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785936128046276474)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PRE-INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'v_seq number;',
'v_proposta number;',
'begin',
'',
'    :P116_COD_SIT_SOLICITACAO := ''1'';',
'	--',
'  begin',
'	SELECT seq_requisicao.NEXTVAL',
'  INTO v_seq ',
'  FROM DUAL;',
'  end;',
'  ',
'  :P116_COD_SOLICITACAO := v_seq;',
'	--',
'	:P116_dt_solicitacao := sysdate;	',
'    :P116_dt_sit_solicitacao := sysdate;	',
'	:P116_cod_empresa_solicitante := NVL(:P_EMPRESA_USER, :P116_cod_empresa_solicitante) ;',
'	:P116_mat_solicitante         := NVL(:P_MATRICULA_USER, :P116_mat_solicitante);',
'	:P116_usuario             := :P_USUARIO;',
'    :P116_dt_atualizacao      := sysdate;',
'',
':p116_IND_VAGA_SIMULTANEA := nvl(:p116_ind_vaga_simultanea, ''N'');',
':p116_ALT_CARGO_TREIN_PROP := nvl(:p116_ALT_CARGO_TREIN_PROP,''N'');',
'',
'IF :P116_PERC_BENEFICIO_VARIAVEL > 0 THEN',
':P116_PERC_BENEFICIO_VAR_PROP := ROUND((NVL(nvl(:P116_remuneracao_variavel_PROP,:P116_remuneracao_variavel),0) + NVL(nvl(:P116_VLR_AUX_TIPO_MOD_PROP,:P116_VLR_AUX_TIPO_MODALIDADE),0)) / ( NVL(nvl(:P116_salario_PROP,:P116_SALARIO),0) + nvl(NVL(:P116_r'
||'emuneracao_variavel_PROP,:P116_remuneracao_variavel),0) + NVL(nvl(:P116_VLR_AUX_TIPO_MOD_PROP,:P116_VLR_AUX_TIPO_MODALIDADE),0)),4) * 100;',
'END IF;',
'',
'IF :p116_COD_PROPOSTA IS NULL THEN',
'    --',
'    BEGIN',
'      --',
'      SELECT SEQ_SOLICITACAO_PROPOSTAS.NEXTVAL',
'        into v_proposta',
'        FROM DUAL;',
'  --',
'  :p116_COD_PROPOSTA := v_proposta;',
'',
'    EXCEPTION',
'        --',
'        WHEN OTHERS THEN',
'        :p116_ok       := ''N'';',
'        :p116_flag     := ''N'';',
unistr('        :p116_mensagem := ''Ocorreu o seguinte erro ao buscar o c\00F3digo sequencial da proposta: '' || SQLERRM;'),
unistr('        apex_application.g_print_success_message := ''Ocorreu o seguinte erro ao buscar o c\00F3digo sequencial da proposta: '' || SQLERRM;'),
'    END;',
'END IF;',
'',
'end;'))
,p_process_error_message=>'#SQLERRM#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P116_ROWID'
,p_process_when_type=>'ITEM_IS_NULL'
);
end;
/
begin
