'  else ',
'  EXECUTE IMMEDIATE ''ALTER SESSION SET NLS_NUMERIC_CHARACTERS= '''',.'''' '';',
'  end if; ',
' ',
'v_total_remuneracao_prop := :P116_TOTAL_REMUNERACAO_PROP;--REPLACE(:P116_TOTAL_REMUNERACAO_PROP,'','',''.'');',
