wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785927344027276471)
,p_process_sequence=>130
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Insere Dados se estiver nulo_1'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'  for l1 in (',
'  select s.cod_solicitacao, s.cargo cargo_req, s.dt_cargo dt_cargo_req',
'      , s.cod_sub_ccusto cod_sub_ccusto_s --ch44534_1',
'      , i.*',
'    from solicitacao_alteracao_func s, informacoes_funcionais_cad i',
'  where s.cod_empresa_solicitado = i.cod_empresa',
'    and s.mat_solicitado = i.matricula',
'    and s.cod_solicitacao = :p116_cod_solicitacao)',
'  loop',
'',
'    if (l1.cargo_req is null OR l1.dt_cargo_req is null) ',
'    or (l1.cod_sub_ccusto is not null and l1.cod_sub_ccusto_s is null) --ch44534_1',
'    then',
'',
'      update solicitacao_alteracao_func',
'         set cad_vaga = l1.cad_vaga,',
'             filial = l1.filial,',
'             cod_ccusto = l1.cod_ccusto,',
'             cod_sub_ccusto = nvl(l1.cod_sub_ccusto,cod_sub_ccusto), --ch44534_1',
'             unidade_adm = l1.unidade_adm,',
'             cod_atividade = l1.cod_atividade,',
'             cargo = l1.cargo,',
'            -- cod_un_negocios = l1.cod_un_negocios,',
'             --dt_admissao = l1.dt_admissao,',
'             dt_filial = l1.dt_filial,',
'             mot_alt_filial = l1.mot_alt_filial,',
'             dt_ccusto = l1.dt_ccusto,',
'             mot_alt_centro = l1.mot_alt_centro,',
'            -- valor_faturavel = l1.valor_faturavel,',
'             dt_cargo = l1.dt_cargo,',
'             mot_alt_cargo = l1.mot_alt_cargo,',
'             funcao = l1.funcao,',
'             dt_funcao = l1.dt_funcao,',
'             mot_alt_funcao = l1.mot_alt_funcao,',
'             cod_local_trab = l1.cod_localizacao,',
'             num_sind_diss = l1.num_sind_diss,',
'             mot_alt_sal = l1.mot_alt_sal,',
'             dt_salario = l1.dt_salario,',
'             grupo_salarial = l1.grupo_salarial,',
'             cod_cat_grupos_salariais = l1.cod_cat_grupos_salariais,',
'             ponto_de_fx = l1.ponto_de_fx,',
'             salario = l1.salario,',
'             remuneracao_variavel = l1.remuneracao_variavel,',
'             total_remuneracao = NVL(L1.SALARIO,0)+NVL(L1.REMUNERACAO_VARIAVEL,0), -- l1.total_remuneracao,',
'             situacao = l1.situacao,',
'             dt_situacao = l1.dt_situacao,',
'             mot_alt_situacao = l1.mot_alt_situacao,',
'             reg_trab = l1.reg_trab,',
'             dt_reg_trab = l1.dt_reg_trab,',
'             mot_alt_reg_trab = l1.mot_alt_reg_trab,',
'             cod_horario = l1.cod_horario,',
'             dt_horario = l1.dt_horario,',
'             mot_alt_horario = l1.mot_alt_horario,',
'             tipo_modalidade = l1.tipo_modalidade,',
'             Vlr_Aux_Tipo_Modalidade = l1.Vlr_Aux_Tipo_Modalidade',
'      where cod_solicitacao = l1.cod_solicitacao;',
'',
'      commit;',
'',
'    end if;',
'',
'  end loop;',
'',
'exception',
'when others then',
'null;',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785938114853276475)
,p_process_sequence=>140
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'POST-INSERT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'cursor c1 is',
'select cod_solicitacao',
'  from solicitacao_propostas',
' where cod_empresa_solicitado = :p116_cod_empresa_solicitado',
'   and cod_solicitacao = :p116_cod_solicitacao;',
'   ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
':p116_mensagem := null;',
'/*',
' if :P116_REMUNERACAO_VARIAVEL_PROP IS NULL THEN',
'        delete Req_Beneficios_Itens',
'        where  Cod_Req_Alt_Func = :P116_COD_SOLICITACAO;',
'        delete req_beneficios_itens_temp',
'        where  matricula = :P116_MAT_SOLICITADO',
'        and    cod_empresa = :p116_COD_EMPRESA_SOLICITADO;',
' end if;',
'*/',
'    pkg_alt_func.Post_Insert(:p116_cod_empresa_solicitado',
'                            ,:P116_COD_SOLICITACAO',
'                            ,:p116_cod_proposta',
'                            ,:p116_parc_salario',
'                            ,v_flg_retorno',
'                            ,v_msg_retorno',
'                            ,:P116_DT_VIGENCIA',
'                            ,:P116_MOT_ALT_VAGA);',
'                                    ',
' if trim(v_msg_retorno) is not null then',
'    :p116_ok       := ''N'';',
'    :p116_flag     := v_flg_retorno;',
'    :p116_mensagem := v_msg_retorno;',
'    apex_application.g_print_success_message := v_msg_retorno;',
' else',
'    :p116_flag     := null;',
'    :p116_mensagem := null;',
'    :p116_ok       := ''S'';',
' end if;',
'',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(785890230898276458)
,p_process_success_message=>unistr('Requisi\00E7\00E3o Criada com Sucesso!')
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785936963617276475)
,p_process_sequence=>150
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'POST-INSERT Benef'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'v_item_validacao varchar2(100) := :P116_ITEM_VALIDACAO;',
'',
'cursor c1 is',
'   select nvl(r.quantidade,1)*r.valor valor_total',
'     from REQ_BENEFICIOS_ITENS_TEMP R, BENEFICIOS_FAMILIA B, BENEFICIOS_FAMILIA_TIPO T',
'    where r.cod_empresa = b.cod_empresa',
'      and r.cod_empresa = t.cod_empresa',
'      and r.cod_familia = b.cod_familia',
'      and r.cod_familia = t.cod_familia',
'      and r.tipo_cod_familia = t.tipo_cod_familia',
'      and R.cod_empresa = nvl(:p116_cod_empresa_prop,:p116_cod_empresa_solicitado)',
'      and R.matricula = :p116_mat_solicitado',
'      AND nvl(R.OPERACAO,''Z'') <> ''D'';',
'',
'v_c1 c1%rowtype;',
'',
'begin',
'',
' :p116_flag     := null;',
' :p116_mensagem := null;',
'',
'open c1;',
'fetch c1 into v_c1;',
'close c1;',
'',
'if :P116_REMUNERACAO_VARIAVEL_PROP is not null or nvl(v_c1.valor_total,0) > 0 then',
' pkg_req_beneficio.post_insert(:p116_cod_empresa_solicitado, :P116_MAT_solicitado, NULL, :P116_cod_solicitacao, v_flg_retorno, v_msg_retorno);',
'end if;',
'',
' if trim(v_msg_retorno) is not null then',
'    :P116_ITEM_VALIDACAO := TRIM(UPPER(''POST_INSERT benef''));',
'    :P116_ok       := ''N'';',
'    :P116_flag     := v_flg_retorno;',
'    :P116_mensagem := v_msg_retorno;',
'    apex_application.g_print_success_message := v_msg_retorno;',
' else',
'    :P116_flag     := null;',
'    :P116_mensagem := null;',
'    if v_item_validacao = TRIM(UPPER(''POST_INSERT benef'')) OR v_item_validacao IS NULL then',
'       :P116_OK := ''S'';',
'       :P116_ITEM_VALIDACAO := null;',
'    else',
'       :P116_ITEM_VALIDACAO := v_item_validacao;',
'       :P116_OK := ''N'';',
'    end if;',
' end if;',
' ',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(785890230898276458)
);
end;
/
