wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785784690475276428)
,p_process_sequence=>160
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_api.id(284213078331811641814)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'Interactive Grid - Automatic Row'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    case :APEX$ROW_STATUS',
'    when ''C'' then',
'        insert into SOLIC_APROV_PARC_SALARIO ( COD_SOLICITACAO, ',
'                                               COD_EMPRESA_SOLICITADO,  ',
'                                               MAT_SOLICITADO,',
'                                               COD_PARCELA,',
'                                               VALOR_SALARIO_APROV,',
'                                               DT_VIGENCIA,',
'                                               dt_vig_salario_aprov,',
'                                               MOT_ALT_SAL_APROV,',
'                                               EFETIVACAO,',
'                                               USUARIO,',
'                                               DT_ATUALIZACAO )',
'        values ( :P116_COD_SOLICITACAO, ',
'                 :P116_COD_EMPRESA_SOLICITADO,',
'                 :P116_MAT_SOLICITADO,',
'                 :COD_PARCELA,',
'                 :VALOR_SALARIO_APROV,',
'                 :DT_VIGENCIA,',
'                 :dt_vig_salario_aprov,',
'                 :P116_MOT_ALT_SAL_PROP,',
'                 ''N'',',
'                 :P_USUARIO,',
'                 SYSDATE )',
'        returning rowid into :ROWID;',
'        ',
'        :P116_PARC_SALARIO_UPDATE := ''N'';',
'        ',
'    when ''U'' then',
'        update SOLIC_APROV_PARC_SALARIO',
'           set COD_PARCELA = :COD_PARCELA,',
'               VALOR_SALARIO_APROV = :VALOR_SALARIO_APROV,',
'               DT_VIGENCIA = :DT_VIGENCIA,',
'               dt_vig_salario_aprov = :dt_vig_salario_aprov',
'         where rowid  = :ROWID;',
'         ',
'         :P116_PARC_SALARIO_UPDATE := ''N'';',
'         ',
'    when ''D'' then',
'        delete SOLIC_APROV_PARC_SALARIO',
'         where rowid = :ROWID;',
'         ',
'         :P116_PARC_SALARIO_UPDATE := ''N'';',
'         ',
'    end case;',
'    ',
'    commit;',
'    ',
'end;'))
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Salvo com Sucesso!'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785937366123276475)
,p_process_sequence=>170
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'ON-UPDATE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'v_item_validacao varchar2(200);',
'',
'cursor c1 is',
'  select cod_sit_solicitacao',
'  from   solicitacao_alteracao_func',
'  where  cod_solicitacao        = :p116_cod_solicitacao',
'  and    cod_empresa_solicitado = :p116_cod_empresa_solicitado;',
'  ',
'v_c1 c1%rowtype;',
'',
'begin',
'',
'if :p116_cod_solicitacao is not null then ',
'',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'',
'    if nvl(v_c1.cod_sit_solicitacao,1) <> nvl(:p116_cod_sit_solicitacao,1) then',
'      begin',
'          update solicitacao_alteracao_func ',
'             set cod_sit_solicitacao = :p116_cod_sit_solicitacao ',
'           where cod_solicitacao = :p116_cod_solicitacao ',
'             and cod_empresa_solicitado = :p116_cod_empresa_solicitado; ',
'             ',
'          commit;',
'      exception',
'      when others then',
'        v_flg_retorno := ''N'';',
'        v_msg_retorno := ''Erro ao atualizar registro: ''||sqlerrm;',
'      end;',
'    end if;',
' ',
'end if;',
'                               ',
'if trim(v_msg_retorno) is not null then',
'',
'    if v_flg_retorno = ''N'' then',
'        :P116_ok       := ''N'';',
'        :P116_ITEM_VALIDACAO := TRIM(UPPER(''Valida_Key_Commit2''));',
'    elsif v_flg_retorno = ''Q'' then',
'        :P116_ok       := ''S'';',
'    else',
'        :P116_ok       := ''S'';',
'    end if;',
'',
'    :P116_flag     := v_flg_retorno;',
'    :P116_mensagem := v_msg_retorno;',
'    apex_application.g_print_success_message := v_msg_retorno;',
'else',
'    :P116_flag     := null;',
'    :P116_mensagem := null;',
