wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785940939286276476)
,p_process_sequence=>200
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'POST-UPDATE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'v_flg_retorno varchar2(3);',
'v_msg_retorno varchar2(4000);',
'',
'v_parc_salario varchar2(1) := :P116_PARC_SALARIO_UPDATE;',
'',
'cursor c1 is',
'select salario_prop',
'  from solicitacao_propostas',
'where cod_solicitacao = :p116_cod_solicitacao;',
'',
'v_c1 c1%rowtype;',
'',
'cursor c2 is',
'select parc_salario',
'  from solicitacao_alteracao_func',
'where cod_solicitacao = :p116_cod_solicitacao;',
'',
'v_c2 c2%rowtype;',
'',
'cursor c3 is',
'select cod_solicitacao',
'  from SOLIC_APROV_PARC_SALARIO',
' where cod_solicitacao = :p116_cod_solicitacao;',
' ',
'v_c3 c3%rowtype;',
'',
'begin',
'  ',
'  open c1;',
'  fetch c1 into v_c1;',
'  close c1;',
'  ',
'  open c3;',
'  fetch c3 into v_c3;',
'  close c3;',
'  ',
'  if v_c3.cod_solicitacao is not null then',
'',
'    if    nvl(:P116_PARC_SALARIO,''N'') = ''S'' and ',
'          nvl(:P116_PARC_SALARIO_UPDATE,''N'') = ''S'' and ',
'          ((nvl(:p116_salario_prop,0) <> v_c1.salario_prop) or ',
'           (nvl(v_c2.parc_salario,''N'') = ''N'')) then',
'       v_parc_salario := ''S'';',
'    else',
'       v_parc_salario := :P116_PARC_SALARIO;',
'    end if;',
'  ',
'  else',
'  ',
'   v_parc_salario := nvl(:P116_PARC_SALARIO,''N'');',
'  ',
'  end if;',
'',
'BEGIN',
'',
' update SOLICITACAO_ALTERACAO_FUNC',
'    set /*PAR_JURIDICO = :P116_PAR_JURIDICO, ',
'        PAR_RESP_AREA = :P116_PAR_RESP_AREA,',
'        PAR_RH = :P116_PAR_RH,',
'        */',
'        PARC_SALARIO = v_parc_salario,',
'        COD_SIT_SOLICITACAO = :P116_COD_SIT_SOLICITACAO,',
'        USUARIO = :P_USUARIO,',
'        DT_ATUALIZACAO = SYSDATE',
'  where cod_solicitacao = :P116_COD_SOLICITACAO;',
'  ',
'  COMMIT;',
'  ',
'  END;',
'',
'PKG_alt_func.Post_Update(:P116_cod_empresa_solicitado          ,',
'                         :P116_cod_solicitacao      ,',
'                         V_flg_retorno             ,',
'                         V_msg_retorno             ,',
'                         v_parc_salario);',
'commit;',
' ',
' if v_msg_retorno is not null then',
'    :p116_ok       := ''N'';',
'    :p116_flag     := v_flg_retorno;',
'    :p116_mensagem := v_msg_retorno;',
'    apex_application.g_print_success_message := v_msg_retorno;',
' else',
'    :p116_flag     := null;',
'    :p116_mensagem := null;',
'    :p116_ok       := ''S'';',
' end if;',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_process_success_message=>unistr('Requisi\00E7\00E3o Alterada com Sucesso!')
);
