,p_process_name=>'Insere Dados se estiver nulo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'  for l1 in (',
'  select s.cod_solicitacao, s.cargo cargo_req, s.dt_cargo dt_cargo_req, i.*',
'    from solicitacao_alteracao_func s, informacoes_funcionais_cad i',
