'            -- cod_un_negocios = l1.cod_un_negocios,',
'             --dt_admissao = l1.dt_admissao,',
'             dt_filial = l1.dt_filial,',
'             mot_alt_filial = l1.mot_alt_filial,',
'             dt_ccusto = l1.dt_ccusto,',
'             mot_alt_centro = l1.mot_alt_centro,',
'            -- valor_faturavel = l1.valor_faturavel,',
'             dt_cargo = l1.dt_cargo,',
'             mot_alt_cargo = l1.mot_alt_cargo,',
'             funcao = l1.funcao,',
'             dt_funcao = l1.dt_funcao,',
'             mot_alt_funcao = l1.mot_alt_funcao,',
'             cod_local_trab = l1.cod_localizacao,',
'             num_sind_diss = l1.num_sind_diss,',
'             mot_alt_sal = l1.mot_alt_sal,',
'             dt_salario = l1.dt_salario,',
'             grupo_salarial = l1.grupo_salarial,',
'             cod_cat_grupos_salariais = l1.cod_cat_grupos_salariais,',
'             ponto_de_fx = l1.ponto_de_fx,',
'             salario = l1.salario,',
'             remuneracao_variavel = l1.remuneracao_variavel,',
'             total_remuneracao = NVL(L1.SALARIO,0)+NVL(L1.REMUNERACAO_VARIAVEL,0), -- l1.total_remuneracao,',
'             situacao = l1.situacao,',
'             dt_situacao = l1.dt_situacao,',
'             mot_alt_situacao = l1.mot_alt_situacao,',
'             reg_trab = l1.reg_trab,',
'             dt_reg_trab = l1.dt_reg_trab,',
'             mot_alt_reg_trab = l1.mot_alt_reg_trab,',
'             cod_horario = l1.cod_horario,',
'             dt_horario = l1.dt_horario,',
'             mot_alt_horario = l1.mot_alt_horario,',
'             tipo_modalidade = l1.tipo_modalidade,',
'             Vlr_Aux_Tipo_Modalidade = l1.Vlr_Aux_Tipo_Modalidade',
'      where cod_solicitacao = l1.cod_solicitacao;',
'',
'      commit;',
'',
'    end if;',
'',
'  end loop;',
'',
'exception',
'when others then',
'null;',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
