'',
'begin',
'',
'for l1 in (',
'SELECT cod_solicitacao, cod_empresa_solicitado cod_empresa, mat_solicitado matricula, filial, vinculo, num_sind_diss, cargo ',
' FROM SOLICITACAO_ALTERACAO_FUNC ',
'WHERE (FILIAL IS NULL or vinculo is null or num_sind_diss is null or cargo is null)',
'  AND COD_SIT_SOLICITACAO in (1,2,5)',
'order by 1 desc)',
'loop',
'',
'open c1(l1.cod_empresa, l1.matricula);',
'fetch c1 into v_c1;',
'close c1;',
'',
'update solicitacao_alteracao_func',
'   set filial = v_c1.filial, vinculo = v_c1.vinculo, cargo = v_c1.cargo, num_sind_diss = v_c1.num_sind_diss',
' where cod_solicitacao = l1.cod_solicitacao;',
' ',
' commit;',
'',
'end loop;',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
