wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(785929317571276472)
,p_process_sequence=>240
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'(Ajuste) Total Remuneracao Apagada'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    ',
'  for l1 in (',
'  select a.cod_solicitacao, ',
'         a.dt_solicitacao, ',
'         a.cod_sit_solicitacao, ',
'         a.salario,',
'         p.salario_prop, ',
'         a.remuneracao_variavel,',
'         p.remuneracao_variavel_prop, ',
'         a.total_remuneracao,',
'         p.total_remuneracao_prop,',
'         (nvl(nvl(p.salario_prop, a.salario),0) + nvl(nvl(p.remuneracao_variavel_prop, a.remuneracao_variavel),0)) total',
'    from solicitacao_alteracao_func a,',
'         solicitacao_propostas p',
'   where a.cod_solicitacao = p.cod_solicitacao',
'     and a.cod_solicitacao = :P116_COD_SOLICITACAO',
'     and (nvl(p.salario_prop,0) > 0 or nvl(p.remuneracao_variavel_prop,0) > 0)',
'     and nvl(p.total_remuneracao_prop,0) <> (nvl(nvl(p.salario_prop, a.salario),0) + nvl(nvl(p.remuneracao_variavel_prop, a.remuneracao_variavel),0))',
'   order by a.cod_solicitacao desc)',
'  loop',
'    ',
'  update solicitacao_propostas',
'     set total_remuneracao_prop = l1.total',
'   where cod_solicitacao = l1.cod_solicitacao;',
'',
'  update solicitacao_aprovadas',
'     set total_remuneracao_aprov = l1.total',
'   where cod_solicitacao = l1.cod_solicitacao;',
'   ',
'  end loop;',
'  ',
'commit;',
'',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'SAVE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
);
