'     into  :P116_COD_CATEGORIA_NVL',
'      from SOLICITACAO_PROPOSTAS',
'    where cod_solicitacao = :p116_cod_solicitacao;',
'',
'    end;',
'',
'end if;',
'',
'exception',
'when others then',
'null;',
'--raise_application_error(-20101, ''Erro ao consultar tabela.'');',
'END;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P116_ROWID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
