'            REG_TRAB_PROP||'' - ''||(SELECT INITCAP(d.desc_regime) FROM REG_TRABALHO d WHERE d.cod = sp.REG_TRAB_PROP AND d.cod_empresa = sp.emp_vaga_prop) reg_trab_dsp,',
'            COD_HORARIO_PROP||'' - ''||(SELECT initcap(d.desc_horario) from cad_horario_trabalho d WHERE d.cod_horario = sp.cod_horario_prop and d.cod_empresa = sp.emp_vaga_prop) horario',
'     into ',
