'      BEGIN',
'      OPEN C1;',
'      FETCH C1 INTO V_C1;',
'      CLOSE C1;',
'      ',
'        if :p116_salario_prop is not null then',
'            :p116_perc_salario := round(((NVL(V_C1.salario_prop,0) / NVL(V_C1.salario,1)) - 1) * 100,4);',
'        end if;',
'        ',
'        if :P116_REMUNERACAO_VARIAVEL_PROP is not null then',
'           :P116_PERC_REMUNERACAO_VAR_PROP := round(((NVL(V_C1.REMUNERACAO_VARIAVEL_PROP,0) / NVL(V_C1.REMUNERACAO_VARIAVEL,1)) - 1) * 100,4);',
'        end if;',
'        ',
'        if :P116_TOTAL_REMUNERACAO_PROP is not null then',
'           :P116_PERC_TOTAL_REMUNERACAO := round(((NVL(V_C1.TOTAL_REMUNERACAO_PROP,0) / NVL(V_C1.TOTAL_REMUNERACAO,1)) - 1) * 100,4);',
'        end if;',
'        ',
'      EXCEPTION',
'      WHEN OTHERS THEN',
'      NULL;',
'      END;',
'      ',
'    END IF;   ',
'',
'    IF :P116_PERC_REMUNERACAO_VAR_PROP IS NOT NULL THEN',
'    :P116_REQ_BENEFICIOS := ''S'';',
'    END IF;',
'',
'    exception',
'    when others then',
'    null;',
'    end;',
'/*',
':P116_SIND_PONTO_DE_FX_NVL := :P116_SINDICATO_PONTO_DE_FX;',
':P116_COD_CATEGORIA_NVL := :P116_COD_CATEGORIA_VAGA;',
