'    :p116_vaga_vlr_aux_tp_modal_prop := :P116_VLR_AUX_TIPO_MOD_PROP;',
'    :p116_vaga_valor_fat_prop        := :P116_valor_faturavel_prop;',
'  END IF;',
'',
'end if;',
'',
'exception',
'when others then ',
'null;',
'',
'END;'))
