,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'',
'cursor c1 is',
'select sum(nvl(b.valor,0) * nvl(b.quantidade,1)) soma',
'  from REQ_BENEFICIOS_ITENS_TEMP B, beneficios_fam_tipo_vlr v',
' where b.cod_empresa = v.cod_empresa',
'   and b.cod_familia = v.cod_familia',
'   and b.tipo_cod_familia = v.tipo_cod_familia',
'   and v.desconta_saldo = ''S''',
'   and nvl(b.operacao,''X'') <> ''D''',
'   and B.cod_empresa = :p116_cod_empresa_solicitado',
'   and B.matricula = :p116_mat_solicitado;',
'   ',
'v_c1 c1%rowtype;',
'',
'v_total number;',
'v_saldo number;',
'',
'cursor c_rem_var is',
'select remuneracao_variavel_prop valor',
'  from solicitacao_propostas',
'where cod_solicitacao = :p116_cod_solicitacao;',
'',
'v_rem_var c_rem_var%rowtype;',
'',
'cursor c2 is',
'select remuneracao_variavel',
'  from informacoes_funcionais',
' where cod_empresa = :p116_cod_empresa_solicitado',
'   and matricula  = :p116_mat_solicitado;',
'',
'v_c2 c2%rowtype;',
'',
'begin',
'',
'  open c_rem_var;',
'  fetch c_rem_var into v_rem_var;',
'  close c_rem_var;',
'  ',
'  if v_rem_var.valor is not null then',
'',
'  :p116_req_beneficios := ''S'';',
'  ',
'    pkg_req_beneficio.insere_benef_obrigatorio (:p116_cod_empresa_solicitado,',
'                                        :p116_mat_solicitado,',
'                                        v_total,',
'                                        v_saldo,',
'                                        null,',
'                                        :p116_cod_solicitacao);',
'',
'  --  if nvl(:P116_PERC_BENEFICIO_VAR_PROP,0) > 0 then',
'  ',
'    open c1;',
'    fetch c1 into v_c1;',
'    close c1;',
'    ',
'    open c2;',
'    fetch c2 into v_c2;',
'    close c2;',
'  ',
'    :p116_total := nvl(:p116_remuneracao_variavel_prop,v_c2.remuneracao_variavel);',
'    :p116_saldo := nvl(:p116_remuneracao_variavel_prop,v_c2.remuneracao_variavel) - nvl(v_c1.soma,0);',
'/*',
'    else',
'',
'    :p116_total := v_total;',
'    :p116_saldo := v_saldo;',
'',
'    end if;',
'*/',
' end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
